def client_ip(request):
    """The visitor's IP. X-Forwarded-For is only trusted for the hops our own proxies added (TRUSTED_PROXY_COUNT,
    1 = nginx in front of gunicorn): entries further left are typed by the client and could be forged to dodge the
    login throttle or fake the audit log."""
    remote = request.META.get('REMOTE_ADDR')
    proxies = int(getattr(settings, 'TRUSTED_PROXY_COUNT', 1) or 0)
    forwarded = [part.strip() for part in (request.META.get('HTTP_X_FORWARDED_FOR') or '').split(',') if part.strip()]
    if proxies <= 0 or not forwarded:
        return remote
    return forwarded[-min(proxies, len(forwarded))]


def describe_user_agent(user_agent):
    ua = user_agent or ''
    if 'Windows' in ua:
        os_label = 'ویندوز'
    elif 'Android' in ua:
        os_label = 'اندروید'
    elif 'iPhone' in ua or 'iPad' in ua:
        os_label = 'iOS'
    elif 'Macintosh' in ua or 'Mac OS' in ua:
        os_label = 'مک'
    elif 'Linux' in ua:
        os_label = 'لینوکس'
    else:
        os_label = 'دستگاه نامشخص'
    if 'Edg/' in ua or 'Edge' in ua:
        browser = 'Edge'
    elif 'Chrome' in ua and 'Chromium' not in ua:
        browser = 'Chrome'
    elif 'Firefox' in ua:
        browser = 'Firefox'
    elif 'Safari' in ua and 'Chrome' not in ua:
        browser = 'Safari'
    else:
        browser = ''
    return f'{os_label} - {browser}' if browser else os_label


def _erd_value(value):
    # ERD ids are uuid columns on PostgreSQL but text on SQLite; the views compare, join and json.dumps them as str.
    return str(value) if isinstance(value, uuid.UUID) else value


def dictfetchall(cursor):
    columns = [column[0] for column in cursor.description]
    return [{column: _erd_value(value) for column, value in zip(columns, row)} for row in cursor.fetchall()]


def dictfetchone(cursor):
    columns = [column[0] for column in cursor.description]
    row = cursor.fetchone()
    return {column: _erd_value(value) for column, value in zip(columns, row)} if row else None


def erd_adapt_sql(sql):
    if connection.vendor != 'sqlite':
        return sql
    adapted = sql.replace('::uuid', '').replace('::int', '').replace('::numeric', '').replace('::text', '')
    adapted = adapted.replace(' ILIKE ', ' LIKE ')
    adapted = adapted.replace('now()', "datetime('now')")
    adapted = adapted.replace(
        "COALESCE(to_char(COALESCE(e.start_at, e.approved_at), 'YYYY/MM/DD'), '-')",
        "COALESCE(replace(substr(COALESCE(e.start_at, e.approved_at), 1, 10), '-', '/'), '-')",
    )
    adapted = adapted.replace(
        "to_char(e.start_at, 'YYYY/MM/DD')",
        "replace(substr(e.start_at, 1, 10), '-', '/')",
    )
    adapted = adapted.replace(
        "COALESCE(to_char(e.start_at, 'HH24:MI'), '-')",
        "COALESCE(substr(e.start_at, 12, 5), '-')",
    )
    adapted = adapted.replace(
        "COALESCE(to_char(e.end_at, 'HH24:MI'), '-')",
        "COALESCE(substr(e.end_at, 12, 5), '-')",
    )
    adapted = adapted.replace(
        "COALESCE(to_char(e.start_at, 'YYYY/MM/DD HH24:MI'), '-')",
        "COALESCE(replace(substr(e.start_at, 1, 16), '-', '/'), '-')",
    )
    adapted = adapted.replace(
        "COALESCE(to_char(e.end_at, 'YYYY/MM/DD HH24:MI'), '-')",
        "COALESCE(replace(substr(e.end_at, 1, 16), '-', '/'), '-')",
    )
    if not erd_has_column('exams', 'lifecycle_status'):
        inferred_lifecycle = (
            "CASE "
            "WHEN COALESCE(e.is_cancelled, false) THEN 'closed' "
            "WHEN COALESCE(e.is_published, false) THEN 'published' "
            "WHEN COALESCE(e.approval_status, '') = 'pending' THEN 'pending_approval' "
            "ELSE 'draft' END"
        )
        adapted = adapted.replace("COALESCE(e.lifecycle_status, '')", inferred_lifecycle)
        adapted = adapted.replace("COALESCE(e.lifecycle_status, '-') AS lifecycle_status", f"{inferred_lifecycle} AS lifecycle_status")
    return adapted


def _erd_parse_json_field(value):
    """Normalize a jsonb/JSON column read via a raw cursor: Postgres (psycopg2)
    already returns dict/list; SQLite has no native JSON type and returns the
    raw text, so it needs json.loads. Returns None if the value is empty or
    not valid JSON."""
    if value in (None, ''):
        return None
    if isinstance(value, (dict, list)):
        return value
    try:
        return json.loads(value)
    except (TypeError, ValueError):
        return None


_ERD_TO_CHAR = re.compile(r"to_char\((COALESCE\(e\.start_at, e\.approved_at\)|e\.start_at|e\.end_at), '")
_ERD_GREGORIAN_TEXT = re.compile(r'^((?:19|20)\d\d)/(\d\d)/(\d\d)((?: \d\d:\d\d)?)$')


def _erd_local_to_char(sql):
    """to_char() of an exam moment runs in the database session's zone (UTC); format it in the site's zone (Tehran)."""
    if connection.vendor != 'postgresql' or 'to_char(' not in sql:
        return sql
    return _ERD_TO_CHAR.sub(lambda m: f"to_char({m.group(1)} AT TIME ZONE '{settings.TIME_ZONE}', '", sql)


def _erd_jalali_texts(rows):
    """Dates formatted by to_char ('YYYY/MM/DD[ HH24:MI]') are shown as Jalali dates, like every other date on the site."""
    from .templatetags.core_extras import display_date_parts
    for row in rows:
        for key, value in row.items():
            match = _ERD_GREGORIAN_TEXT.match(value) if isinstance(value, str) else None
            if match:
                jy, jm, jd, _months = display_date_parts(int(match.group(1)), int(match.group(2)), int(match.group(3)))
                row[key] = f'{jy:04d}/{jm:02d}/{jd:02d}{match.group(4)}'
    return rows


def erd_rows(sql, params=None):
    formats_dates = 'to_char(' in sql
    sql = _erd_local_to_char(erd_adapt_sql(sql))
    with connection.cursor() as cursor:
        cursor.execute(sql, params or [])
        rows = dictfetchall(cursor)
    return _erd_jalali_texts(rows) if formats_dates else rows


def erd_row(sql, params=None):
    formats_dates = 'to_char(' in sql
    sql = _erd_local_to_char(erd_adapt_sql(sql))
    with connection.cursor() as cursor:
        cursor.execute(sql, params or [])
        row = dictfetchone(cursor)
    return _erd_jalali_texts([row])[0] if formats_dates and row else row


def erd_execute(sql, params=None):
    sql = erd_adapt_sql(sql)
    with connection.cursor() as cursor:
        cursor.execute(sql, params or [])


def erd_sync_login_account(username, *, is_active=True, reset_password=False):
    """ایجاد/به‌روزرسانی حساب ورود جنگویی (auth_user) هم‌نام با پروفایل ERD.

    ثبت پروفایل در جدول‌های ERD به‌تنهایی کاربر را قادر به ورود نمی‌کند،
    چون احراز هویت Django روی جدول auth_user و رمز هش‌شده‌ی آن کار می‌کند.
    این تابع تضمین می‌کند هر پروفایلی که نقش می‌گیرد یک کاربر Django هم‌نام
    با رمز عبور واقعی داشته باشد. رمز تولیدشده را برمی‌گرداند تا به مدیر
    نمایش داده شود (فقط وقتی کاربر تازه ساخته شده یا reset_password=True).
    """
    username = (username or '').strip()
    if not username:
        return None, None
    user, created = User.objects.get_or_create(username=username, defaults={'is_active': is_active})
    if not created and _erd_login_is_leftover(user):
        # the login of a deleted account with this username (older deletes kept it): the new account must not get
        # its password, sessions or authenticator, and the admin must be shown a password for it
        account_security.forget_login(user)
        reset_password = True
    generated_password = None
    if created or reset_password:
        generated_password = account_security.generate_temporary_password()
        user.set_password(generated_password)
    if user.is_active != is_active:
        user.is_active = is_active
    if not user.email:  # lets the account sign in with its e-mail too (StyledAuthenticationForm.resolve_username)
        profile = erd_row("SELECT email FROM profiles WHERE username = %s AND COALESCE(email, '') <> '' LIMIT 1", [username])
        email = (profile or {}).get('email') or ''
        if email and not User.objects.filter(email__iexact=email).exclude(pk=user.pk).exists():
            user.email = email
    user.save()
    if generated_password:
        account_security.mark_password_set(user)  # new password: earlier failed sign-ins with this name stop counting
    return user, generated_password


def _erd_login_is_leftover(user) -> bool:
    """An existing auth_user whose profile was created just now, after the login itself: it belonged to an account
    that was deleted (its profile went, the login stayed) and a new account with the same username was made."""
    row = erd_row(
        """
        SELECT 1 AS hit FROM profiles
        WHERE username = %s AND created_at > %s AND created_at > %s
        LIMIT 1
        """,
        [user.username, user.date_joined + timedelta(seconds=5), timezone.now() - timedelta(minutes=10)],
    )
    return bool(row)


@lru_cache(maxsize=64)
def erd_table_columns(table):
    try:
        with connection.cursor() as cursor:
            cursor.execute(f'SELECT * FROM {table} LIMIT 0')
            return {column[0] for column in cursor.description or []}
    except Exception:
        return set()


def erd_has_column(table, column):
    return column in erd_table_columns(table)


def _db_naive_datetime(value):
    """A naive datetime read from the database. PostgreSQL 'timestamp without time zone' columns hold UTC (Django
    runs its connections in UTC); SQLite text without an offset is local time."""
    if connection.vendor == 'postgresql':
        return value.replace(tzinfo=dt_timezone.utc)
    return timezone.make_aware(value, timezone.get_current_timezone())


def erd_datetime(value):
    if isinstance(value, datetime) and timezone.is_naive(value):
        return _db_naive_datetime(value)
    if not value or hasattr(value, 'date'):
        return value
    value = str(value).strip()
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError:
        return None
    if timezone.is_naive(parsed):
        parsed = timezone.make_aware(parsed, timezone.get_current_timezone())
    return parsed


def erd_count(table, where='', params=None):
    sql = f'SELECT COUNT(*) AS count FROM {table}'
    if where:
        sql += f' WHERE {where}'
    row = erd_row(sql, params or [])
    return row['count'] if row else 0


# Organisational structure: fixed levels (apps/core/org_levels.py). For the unit pickers of the account wizards a
# unit's depth is 1 = دانشگاه (level 2 of the system), 2 = بخش (level 3).
ORG_UNIT_PICKER_LEVELS = [
    {'title': 'دانشگاه', 'hint': 'سطح ۲ — زیرمجموعه‌ی مدیر سیستم'},
    {'title': 'بخش', 'hint': 'سطح ۳ — زیرمجموعه‌ی دانشگاه'},
]


def repair_display_text(value):
    text = str(value or '').strip()
    if not any(marker in text for marker in ('Ø', 'Ù', 'Û', 'Ã', 'Â', 'â')):
        return text
    for _ in range(3):
        try:
            repaired = text.encode('cp1252').decode('utf-8')
        except UnicodeError:
            break
        if repaired == text:
            break
        text = repaired
    return text


def get_org_level_config():
    """Titles of the unit picker's selects (دانشگاه › بخش); the levels are fixed, see org_levels.py."""
    return [dict(level) for level in ORG_UNIT_PICKER_LEVELS]


def org_unit_level_index(unit):
    """Depth of a unit in the pickers: 1 = university, 2 = department (old faculty/group units count as 2)."""
    return 1 if unit.get('type') == 'university' else 2


def _xlsx_column_name(index):
    name = ''
    while index:
        index, remainder = divmod(index - 1, 26)
        name = chr(65 + remainder) + name
    return name


def _xlsx_cell_value(cell, shared_strings):
    ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    cell_type = cell.attrib.get('t')
    if cell_type == 's':
        value = cell.findtext('m:v', default='', namespaces=ns)
        return shared_strings[int(value)] if value.isdigit() and int(value) < len(shared_strings) else ''
    if cell_type == 'inlineStr':
        return ''.join(cell.itertext()).strip()
    return cell.findtext('m:v', default='', namespaces=ns).strip()


def read_xlsx_dicts(uploaded_file):
    return [row for _number, row in read_xlsx_numbered_rows(uploaded_file)]


def read_xlsx_numbered_rows(uploaded_file):
    """[(row number in the sheet, {header: value})] of the first sheet's non-empty rows (row 1 is the header)."""
    ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    with zipfile.ZipFile(uploaded_file) as archive:
        shared_strings = []
        if 'xl/sharedStrings.xml' in archive.namelist():
            shared_root = ET.fromstring(archive.read('xl/sharedStrings.xml'))
            for item in shared_root.findall('m:si', ns):
                shared_strings.append(''.join(item.itertext()).strip())

        sheet_name = 'xl/worksheets/sheet1.xml'
        if sheet_name not in archive.namelist():
            sheet_name = next((name for name in archive.namelist() if name.startswith('xl/worksheets/sheet')), None)
        if not sheet_name:
            return []

        root = ET.fromstring(archive.read(sheet_name))
        rows = []
        for position, row in enumerate(root.findall('.//m:sheetData/m:row', ns), start=1):
            values = {}
            for cell in row.findall('m:c', ns):
                ref = cell.attrib.get('r', '')
                column = ''.join(ch for ch in ref if ch.isalpha())
                values[column] = _xlsx_cell_value(cell, shared_strings)
            number = row.attrib.get('r', '')
            rows.append((int(number) if number.isdigit() else position, values))
        if not rows:
            return []

        headers = rows[0][1]
        parsed_rows = []
        for number, row in rows[1:]:
            parsed = {}
            for column, header in headers.items():
                header = (header or '').strip()
                if header:
                    parsed[header] = (row.get(column) or '').strip()
            if any(parsed.values()):
                parsed_rows.append((number, parsed))
        return parsed_rows


def xlsx_response(filename, headers, rows, sheet_name='Sheet1'):
    def cell(ref, value):
        value = xml_escape(str(value or ''))
        return f'<c r="{ref}" t="inlineStr"><is><t>{value}</t></is></c>'

    sheet_rows = []
    for row_index, row_values in enumerate([headers, *rows], start=1):
        cells = ''.join(
            cell(f'{_xlsx_column_name(col_index)}{row_index}', value)
            for col_index, value in enumerate(row_values, start=1)
        )
        sheet_rows.append(f'<row r="{row_index}">{cells}</row>')

    sheet_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
        f'<sheetData>{"".join(sheet_rows)}</sheetData></worksheet>'
    )
    workbook_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
        f'<sheets><sheet name="{xml_escape(sheet_name)}" sheetId="1" r:id="rId1"/></sheets></workbook>'
    )
    rels_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
        '</Relationships>'
    )
    workbook_rels_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
        '</Relationships>'
    )
    content_types_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        '<Default Extension="xml" ContentType="application/xml"/>'
        '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
        '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
        '</Types>'
    )

    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, 'w', zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('[Content_Types].xml', content_types_xml)
        archive.writestr('_rels/.rels', rels_xml)
        archive.writestr('xl/workbook.xml', workbook_xml)
        archive.writestr('xl/_rels/workbook.xml.rels', workbook_rels_xml)
        archive.writestr('xl/worksheets/sheet1.xml', sheet_xml)
    buffer.seek(0)

    response = HttpResponse(
        buffer.getvalue(),
        content_type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    )
    response['Content-Disposition'] = f'attachment; filename="{filename}"'
    return response


def erd_profile_for_user(user):
    if not user or not getattr(user, 'is_authenticated', False):
        return None
    sentinel = object()
    cached = getattr(user, '_erd_profile_cache_value', sentinel)
    if cached is not sentinel:
        return cached
    profile = erd_row(
        """
        SELECT *
        FROM profiles
        WHERE username = %s OR email = %s
        ORDER BY CASE WHEN username = %s THEN 0 ELSE 1 END
        LIMIT 1
        """,
        [user.username, user.email or '', user.username],
    )
    user._erd_profile_cache_value = profile
    return profile


def erd_roles_for_profile(profile_id):
    if not profile_id:
        return []
    rows = erd_rows('SELECT role FROM user_roles WHERE user_id = %s ORDER BY created_at', [profile_id])
    return [row['role'] for row in rows]


def erd_primary_role(user):
    """نقش اصلی کاربر در جدول‌های ERD، یا None اگر هیچ نقشی برایش ثبت نشده باشد.

    قبلاً وقتی پروفایل/نقشی پیدا نمی‌شد، به‌صورت پیش‌فرض 'student' برمی‌گشت که
    یک حفره‌ی امنیتی بود (کاربر بدون پروفایل، بی‌صدا به‌عنوان دانشجو تلقی
    می‌شد). فراخوان‌ها باید None را به‌عنوان «بدون نقش/دسترسی رد شود» تلقی
    کنند، نه اینکه خودشان دوباره پیش‌فرض دیگری جایگزین کنند.
    """
    if hasattr(user, '_erd_primary_role_cache'):
        return user._erd_primary_role_cache
    profile = erd_profile_for_user(user)
    roles = getattr(user, '_erd_roles_cache', None)
    if roles is None:
        roles = erd_roles_for_profile(profile['id'] if profile else None)
        user._erd_roles_cache = roles
    for role in ('admin', 'academic_manager', 'teacher', 'student'):
        if role in roles:
            user._erd_primary_role_cache = role
            return role
    user._erd_primary_role_cache = None
    return None


def erd_role_required(*allowed_roles):
    def decorator(view_func):
        @login_required
        @wraps(view_func)
        def wrapped(request, *args, **kwargs):
            role = erd_primary_role(request.user)
            if role not in allowed_roles:
                return HttpResponseForbidden('دسترسی برای این نقش مجاز نیست.')
            profile = erd_profile_for_user(request.user)
            request.erd_profile = profile
            request.erd_profile_id = profile['id'] if profile else None
            request.erd_role = role
            if role != 'teacher' or not request.erd_profile_id:
                return view_func(request, *args, **kwargs)
            from .teacher_preferences import calendar_for
            from .templatetags.core_extras import CALENDAR

            token = CALENDAR.set(calendar_for(request.erd_profile_id))  # «تقویم تاریخ» of the teacher's settings
            try:
                return view_func(request, *args, **kwargs)
            finally:
                CALENDAR.reset(token)
        return wrapped
    return decorator


