def _teacher_exam_status(row, now) -> tuple:
    """(label, badge tone) of one exam from its lifecycle, cancellation and time window."""
    if row.get('is_cancelled'):
        return 'لغو شده', 'is-muted'
    lifecycle = row.get('lifecycle') or 'draft'
    start_at, end_at = erd_datetime(row.get('start_at')), erd_datetime(row.get('end_at'))
    if lifecycle in ('closed', 'archived') or (lifecycle in ('published', 'in_progress') and end_at and end_at < now):
        return 'پایان‌یافته', 'is-muted'
    if lifecycle in ('published', 'in_progress'):
        return ('در حال برگزاری', 'is-ok') if start_at and start_at <= now else ('برنامه‌ریزی شده', 'is-blue')
    return {
        'approved': ('تأیید شده', 'is-blue'),
        'scheduled': ('زمان‌بندی انتشار', 'is-blue'),
        'pending_approval': ('در انتظار تأیید', 'is-warn'),
    }.get(lifecycle, ('پیش‌نویس', 'is-violet'))


_TEACHER_EXAM_STATE_BY_LABEL = {
    'لغو شده': 'cancelled', 'پایان‌یافته': 'finished', 'در حال برگزاری': 'running', 'برنامه‌ریزی شده': 'scheduled',
    'تأیید شده': 'scheduled', 'زمان‌بندی انتشار': 'scheduled', 'در انتظار تأیید': 'pending_approval', 'پیش‌نویس': 'draft',
}


def _teacher_exam_state_sql() -> str:
    """SQL twin of _teacher_exam_status as a tab key (two %s = now)."""
    lifecycle = "COALESCE(e.lifecycle_status, '')"
    running = f"{lifecycle} IN ('published', 'in_progress')"
    return f"""CASE
        WHEN COALESCE(e.is_cancelled, false) THEN 'cancelled'
        WHEN {lifecycle} IN ('closed', 'archived') OR ({running} AND e.end_at < %s) THEN 'finished'
        WHEN {running} AND e.start_at <= %s THEN 'running'
        WHEN {running} OR {lifecycle} IN ('approved', 'scheduled') THEN 'scheduled'
        WHEN {lifecycle} = 'pending_approval' THEN 'pending_approval'
        ELSE 'draft' END"""


def _exam_list_order_sql(sort) -> tuple:
    """ORDER BY of an exam list (sort key from exam_list.SORTS) and its params."""
    if sort == 'oldest':
        return 'e.start_at ASC NULLS LAST, e.title', []
    if sort == 'title':
        return 'e.title, e.start_at DESC', []
    if sort == 'upcoming':  # coming exams nearest first, then past ones newest first, undated last
        now = timezone.now()
        return ('CASE WHEN e.start_at IS NULL THEN 2 WHEN e.start_at >= %s THEN 0 ELSE 1 END, '
                'CASE WHEN e.start_at >= %s THEN e.start_at END ASC, e.start_at DESC, e.title'), [now, now]
    return 'CASE WHEN e.start_at IS NULL THEN 0 ELSE 1 END, e.start_at DESC, e.title', []


def _teacher_exam_list(teacher_id, filters: dict, page_number) -> dict:
    """One page of the teacher's own exams with real course, groups, question and participant counts,
    plus tab counts and filter options (exam_list.py)."""
    from django.core.paginator import Paginator

    now = timezone.now()
    query, status = filters['query'], filters['status']
    where, params = ['e.teacher_id = %s'], [teacher_id]
    if query:
        code = _normalize_exam_code(query)
        if code:
            where.append("(e.title LIKE %s OR REPLACE(CAST(e.id AS text), '-', '') LIKE %s)")
            params.extend([f'%{query}%', f'{code}%'])
        else:
            where.append('e.title LIKE %s')
            params.append(f'%{query}%')
    if filters['course']:
        where.append('CAST(e.course_id AS text) = %s')
        params.append(filters['course'])
    if filters['group']:
        where.append('e.id IN (SELECT exam_id FROM exam_assignments WHERE CAST(group_id AS text) = %s)')
        params.append(filters['group'])
    if filters.get('class_group'):  # (course id, group id): the exams of one class (teacher_class.py)
        where.append('(e.course_id = %s OR e.id IN (SELECT exam_id FROM exam_assignments WHERE group_id = %s))')
        params.extend(filters['class_group'])
    low, high = exam_list.date_bounds(filters['date'], now)
    if low == 'unset':
        where.append('e.start_at IS NULL')
    elif low == 'past':
        where.append('e.start_at < %s')
        params.append(high)
    elif low is not None:
        where.append('e.start_at >= %s AND e.start_at < %s')
        params.extend([low, high])
    state_sql = _teacher_exam_state_sql()
    base = f"SELECT e.id, {state_sql} AS state FROM exams e WHERE {' AND '.join(where)}"
    base_params = [now, now, *params]
    counts = {row['state']: row['count'] for row in erd_rows(
        f'SELECT x.state, COUNT(*) AS count FROM ({base}) x GROUP BY x.state', base_params)}
    states = ['scheduled', 'running'] if status == 'active' else [status] if status != 'all' else []
    state_where = f"WHERE x.state IN ({', '.join(['%s'] * len(states))})" if states else ''

    total = sum(counts.get(key, 0) for key in states) if states else sum(counts.values())
    page = Paginator(range(total), TEACHER_EXAM_LIST_PAGE_SIZE).get_page(page_number)
    order_sql, order_params = _exam_list_order_sql(filters['sort'])
    rows = erd_rows(
        f"""
        SELECT e.id, e.title, COALESCE(c.title, '-') AS course, e.start_at, e.end_at, e.duration_minutes,
               COALESCE(e.lifecycle_status, '') AS lifecycle, COALESCE(e.is_cancelled, false) AS is_cancelled,
               COALESCE(e.is_published, false) AS is_published, COALESCE(e.approval_status, '') AS approval_status
        FROM ({base}) x
        JOIN exams e ON e.id = x.id
        LEFT JOIN courses c ON c.id = e.course_id
        {state_where}
        ORDER BY {order_sql}
        LIMIT %s OFFSET %s
        """,
        [*base_params, *states, *order_params, TEACHER_EXAM_LIST_PAGE_SIZE, page.start_index() - 1 if total else 0],
    )

    figures = _exam_list_figures([str(row['id']) for row in rows])
    for row in rows:
        exam_id = str(row['id'])
        start_at = erd_datetime(row['start_at'])
        row['status_label'], row['status_tone'] = _teacher_exam_status(row, now)
        row['base_label'] = row['status_label']
        row['date_label'] = _jalali_long_date(start_at)
        row['time_label'] = timezone.localtime(start_at).strftime('%H:%M') if start_at else ''
        row.update({key: values.get(exam_id, 0) for key, values in figures.items() if key != 'groups'})
        row['groups_label'] = '، '.join(figures['groups'].get(exam_id, []))
        row['assigned'] = row['assigned'] or None
        # «پایش زنده» while it runs; «نتایج و انتشار» (where results are released) once anyone handed it in or it ended
        row['is_running'] = row['status_label'] == 'در حال برگزاری'
        row['has_results'] = bool(row['is_published']) and (row['submitted'] > 0 or row['status_label'] == 'پایان‌یافته')
        # same rule as _teacher_exam_editable, from the counts already loaded for this page
        row['editable'] = (
            (row['lifecycle'] or 'draft') in ('draft', 'pending_approval')
            and not row['is_published'] and not row['is_cancelled'] and not row['attempts']
        )
        row['status_label'] = _exam_status_with_approval(row['status_label'], row)  # after the label checks above
        _teacher_exam_row_actions(row, _TEACHER_EXAM_STATE_BY_LABEL.get(row['base_label'], 'draft'))

    courses = [{'value': str(row['id']), 'label': row['title']} for row in erd_rows(
        """
        SELECT DISTINCT c.id, c.title FROM exams e JOIN courses c ON c.id = e.course_id
        WHERE e.teacher_id = %s ORDER BY c.title
        """, [teacher_id])]
    groups = [
        {'value': str(row['id']), 'label': f"{row['course_name'] or ''} - گروه {row['group_code']}" if row['group_code'] else row['course_name']}
        for row in erd_rows(
            """
            SELECT DISTINCT sg.id, sg.course_name, sg.group_code FROM exam_assignments ea
            JOIN exams e ON e.id = ea.exam_id JOIN student_groups sg ON sg.id = ea.group_id
            WHERE e.teacher_id = %s ORDER BY sg.course_name, sg.group_code
            """, [teacher_id])
    ]
    return exam_list.listing(rows=rows, page=page, counts=counts, filters=filters, courses=courses, groups=groups)


def _exam_list_figures(exam_ids) -> dict:
    """Per exam id: question / attempt / submitted / started / pending-review / assigned counts and group labels."""
    figures = {key: {} for key in ('question_count', 'attempts', 'submitted', 'started', 'pending_reviews', 'assigned', 'groups')}
    if not exam_ids:
        return figures
    marks = ', '.join(['%s'] * len(exam_ids))
    for row in erd_rows(
        f"""
        SELECT exam_id, COUNT(*) AS attempts, COUNT(DISTINCT student_id) AS started,
               COUNT(DISTINCT CASE WHEN status IN ('submitted', 'graded') THEN student_id END) AS submitted
        FROM exam_attempts WHERE exam_id IN ({marks}) GROUP BY exam_id
        """, exam_ids):
        for key in ('attempts', 'started', 'submitted'):
            figures[key][str(row['exam_id'])] = row[key]
    figures['question_count'] = {str(r['exam_id']): r['count'] for r in erd_rows(
        f'SELECT exam_id, COUNT(*) AS count FROM exam_questions WHERE exam_id IN ({marks}) GROUP BY exam_id', exam_ids)}
    figures['pending_reviews'] = {str(r['exam_id']): r['count'] for r in erd_rows(
        f"""
        SELECT ea.exam_id, COUNT(aa.id) AS count
        FROM attempt_answers aa JOIN exam_attempts ea ON ea.id = aa.attempt_id
        WHERE ea.exam_id IN ({marks}) AND COALESCE(aa.needs_manual_grading, false) = true
        GROUP BY ea.exam_id
        """, exam_ids)}
    for r in erd_rows(
        f"""
        SELECT ea.exam_id, sg.group_code, sg.course_name
        FROM exam_assignments ea JOIN student_groups sg ON sg.id = ea.group_id
        WHERE ea.exam_id IN ({marks})
        ORDER BY sg.course_name, sg.group_code
        """, exam_ids):
        figures['groups'].setdefault(str(r['exam_id']), []).append(f"گروه {r['group_code']}" if r['group_code'] else r['course_name'])
    figures['assigned'] = _teacher_dashboard_participant_counts(exam_ids)
    return figures


def _teacher_exam_row_actions(row, state):
    """Main button, icons and «…» menu of one row on the teacher's exam list (exam_list.present)."""
    from .templatetags.core_extras import fa_digits

    from .exam_hub import HUB_STATES, hub_url

    exam_id = row['id']
    report = reverse('core:teacher_exam_report', args=[exam_id])
    edit = reverse('core:teacher_exam_edit', args=[exam_id]) if row['editable'] else ''
    managed = state in HUB_STATES  # «مدیریت آزمون» (exam_hub) for scheduled / running / finished exams
    results = (hub_url('teacher', exam_id, 'results') if managed else f"{reverse('core:teacher_results')}?exam={exam_id}")         if row['has_results'] else ''
    monitoring = (hub_url('teacher', exam_id, 'live') if managed else f"{reverse('core:teacher_monitoring')}?exam={exam_id}")         if row['is_running'] else ''
    reviews = (hub_url('teacher', exam_id, 'grading') if managed else reverse('core:teacher_reviews')) if row['pending_reviews'] else ''
    if state == 'draft':
        primary = {'label': 'ادامه ویرایش', 'url': edit, 'tone': 'blue'} if edit else {'label': 'جزئیات آزمون', 'url': report, 'tone': 'grey'}
    elif state == 'pending_approval':
        primary = {'label': 'پیگیری تأیید', 'url': report, 'tone': 'amber'}
    elif state == 'scheduled':
        primary = {'label': 'مدیریت آزمون', 'url': hub_url('teacher', exam_id), 'tone': 'blue'}
    elif state == 'running':
        primary = {'label': 'نظارت زنده', 'url': monitoring or hub_url('teacher', exam_id, 'live'), 'tone': 'solid'}
    elif state == 'finished' and reviews:
        primary = {'label': 'تصحیح پاسخ‌ها', 'url': reviews, 'tone': 'amber', 'count': row['pending_reviews']}
    elif state == 'finished':
        primary = {'label': 'نتایج و گزارش‌ها', 'url': hub_url('teacher', exam_id, 'results'), 'tone': 'blue'}
    else:
        primary = {'label': 'جزئیات آزمون', 'url': report, 'tone': 'grey'}
    used = primary['url']
    draft = state == 'draft' and row['editable']
    post = lambda name: reverse(f'core:teacher_exam_{name}', args=[exam_id])  # noqa: E731
    hub = hub_url('teacher', exam_id) if managed else ''
    menu = [
        hub and hub != used and {'label': 'مدیریت آزمون', 'icon': 'live', 'url': hub},
        {'label': 'جزئیات آزمون', 'icon': 'info', 'url': report},
        edit and edit != used and {'label': 'ویرایش آزمون', 'icon': 'edit', 'url': edit},
        monitoring and monitoring != used and {'label': 'پایش زنده', 'icon': 'live', 'url': monitoring},
        results and results != used and {'label': 'نتایج و انتشار', 'icon': 'chart', 'url': results},
        reviews and reviews != used and {'label': f"تصحیح پاسخ‌ها ({fa_digits(row['pending_reviews'])})", 'icon': 'grade', 'url': reviews},
        {'label': 'تکثیر آزمون', 'icon': 'copy', 'post': post('duplicate')},
        draft and {'label': 'ارسال برای تأیید', 'icon': 'send', 'post': post('submit'), 'confirm_ok': 'ارسال',
                   'confirm': 'آزمون برای تأیید مدیر آموزشی ارسال شود؟ تا زمان بررسی هنوز می‌توانید آن را ویرایش کنید.'},
        draft and {'label': 'حذف پیش‌نویس', 'icon': 'trash', 'post': post('delete'), 'danger': True, 'confirm_ok': 'حذف',
                   'confirm': f"پیش‌نویس «{row['title']}» برای همیشه حذف شود؟"},
    ]
    exam_list.present(row, state=state, primary=primary, menu=menu, code=exam_access_code(exam_id),
                      preview_url=f"{reverse('core:exam_preview', args=[exam_id])}?new=1", report_url=report)


# «کلاس‌های فعال» / «کلاس‌های گذشته» tabs (current = not deactivated / archived, drafts included); the older
# status values still work in links.
TEACHER_CLASS_LIST_FILTERS = {'current': 'کلاس‌های فعال', 'past': 'کلاس‌های گذشته',
                              'all': 'همه وضعیت‌ها', 'active': 'فعال', 'inactive': 'غیرفعال / پیش‌نویس'}
TEACHER_CLASS_LIST_PAGE_SIZE = 10
TEACHER_CLASS_AVATARS = 4  # member faces stacked on each class card
# A student's photo as teachers see it: empty when the student switched «نمایش تصویر پروفایل برای استاد» off
# on their settings page. Needs `p` (profiles) and `sp` (student_profiles) in the query.
STUDENT_AVATAR_SQL = "CASE WHEN COALESCE(sp.show_avatar_to_teacher, true) THEN COALESCE(p.avatar_url, '') ELSE '' END"


def _teacher_semester_label(semester, year) -> str:
    """'نیمسال اول ۱۴۰۴-۱۴۰۵' from the free-text semester/year stored on a group."""
    from .templatetags.core_extras import fa_digits

    semester = str(semester or '').strip()
    semester = {'1': 'اول', '2': 'دوم', 'summer': 'تابستان'}.get(semester, semester)
    if semester and not semester.startswith(('نیمسال', 'تابستان')):
        semester = f'نیمسال {semester}'
    return fa_digits(' '.join(part for part in (semester, str(year or '').strip()) if part))


def _teacher_class_list(teacher_id, query: str, term: str, status: str, page_number) -> dict:
    """One page of the groups this teacher teaches (owner or co-teacher), with real member and exam figures."""
    from django.core.paginator import Paginator

    now = timezone.now()
    status_col = "COALESCE(sg.status, 'active')" if erd_has_column('student_groups', 'status') else "'active'"
    is_active = f"(COALESCE(sg.is_active, true) = true AND {status_col} = 'active')"
    own = ['(sg.teacher_id = %s OR sg.id IN (SELECT group_id FROM group_teachers WHERE teacher_id = %s))']
    archived = 'COALESCE(sg.is_archived, false)' if erd_has_column('student_groups', 'is_archived') else 'false'
    is_past = (f"(COALESCE(sg.is_active, true) = false OR {archived} "
               f"OR {status_col} IN ('archived', 'closed', 'inactive', 'finished'))")
    own_params = [teacher_id, teacher_id]

    terms = [
        {'value': f"{row['academic_year'] or ''}|{row['semester'] or ''}", 'label': _teacher_semester_label(row['semester'], row['academic_year'])}
        for row in erd_rows(
            f"SELECT DISTINCT sg.academic_year, sg.semester FROM student_groups sg WHERE {' AND '.join(own)} ORDER BY sg.academic_year DESC, sg.semester DESC",
            own_params,
        )
    ]
    if term not in {item['value'] for item in terms}:
        term = ''

    where, params = list(own), list(own_params)
    if query:
        where.append('(sg.course_name LIKE %s OR c.code LIKE %s OR sg.group_code LIKE %s)')
        params.extend([f'%{query}%'] * 3)
    if term:
        year, semester = term.split('|', 1)
        where.append("COALESCE(sg.academic_year, '') = %s AND COALESCE(sg.semester, '') = %s")
        params.extend([year, semester])
    tab_where_sql, tab_params = ' AND '.join(where), list(params)  # tab counts follow search + term
    if status == 'current':
        where.append(f'NOT {is_past}')
    elif status == 'past':
        where.append(is_past)
    elif status == 'active':
        where.append(f'{is_active} AND NOT {archived}')
    elif status == 'inactive':
        where.append(f'NOT {is_active} AND NOT {archived}')
    where_sql = ' AND '.join(where)
    tab_counts = erd_row(
        f'SELECT SUM(CASE WHEN {is_past} THEN 0 ELSE 1 END) AS current, SUM(CASE WHEN {is_past} THEN 1 ELSE 0 END) AS past '
        f'FROM student_groups sg LEFT JOIN courses c ON c.id = sg.course_id WHERE {tab_where_sql}', tab_params)

    total = erd_row(f'SELECT COUNT(*) AS count FROM student_groups sg LEFT JOIN courses c ON c.id = sg.course_id WHERE {where_sql}', params)['count']
    page = Paginator(range(total), TEACHER_CLASS_LIST_PAGE_SIZE).get_page(page_number)
    not_cancelled = 'COALESCE(e.is_cancelled, false) = false'
    rows = erd_rows(
        f"""
        SELECT sg.id, sg.course_name, c.code AS course_code, sg.group_code, sg.academic_year, sg.semester,
               {status_col} AS status, {is_active} AS is_active,
               (SELECT COUNT(*) FROM student_group_members m WHERE m.group_id = sg.id) AS students_count,
               (SELECT COUNT(DISTINCT e.id) FROM exam_assignments ea JOIN exams e ON e.id = ea.exam_id
                 WHERE ea.group_id = sg.id AND {not_cancelled}) AS exams_count,
               (SELECT MIN(e.start_at) FROM exam_assignments ea JOIN exams e ON e.id = ea.exam_id
                 WHERE ea.group_id = sg.id AND {not_cancelled} AND e.start_at > %s) AS next_exam_at,
               (SELECT MAX(e.start_at) FROM exam_assignments ea JOIN exams e ON e.id = ea.exam_id
                 WHERE ea.group_id = sg.id AND {not_cancelled} AND e.start_at <= %s) AS last_exam_at
        FROM student_groups sg
        LEFT JOIN courses c ON c.id = sg.course_id
        WHERE {where_sql}
        ORDER BY {is_active} DESC, sg.academic_year DESC, sg.course_name, sg.group_code
        LIMIT %s OFFSET %s
        """,
        [now, now, *params, TEACHER_CLASS_LIST_PAGE_SIZE, page.start_index() - 1 if total else 0],
    )

    faces = {}
    group_ids = [str(row['id']) for row in rows]
    if group_ids:
        marks = ', '.join(['%s'] * len(group_ids))
        for face in erd_rows(
            f"""
            SELECT group_id, full_name, avatar_url FROM (
                SELECT m.group_id, m.full_name, {STUDENT_AVATAR_SQL} AS avatar_url,
                       ROW_NUMBER() OVER (PARTITION BY m.group_id ORDER BY m.full_name) AS position
                FROM student_group_members m LEFT JOIN profiles p ON p.id = m.student_user_id
                LEFT JOIN student_profiles sp ON sp.user_id = m.student_user_id
                WHERE m.group_id IN ({marks})
            ) ranked
            WHERE position <= %s
            """,
            [*group_ids, TEACHER_CLASS_AVATARS],
        ):
            faces.setdefault(str(face['group_id']), []).append({
                'name': face['full_name'], 'avatar_url': face['avatar_url'], 'initial': (face['full_name'] or '؟').strip()[:1],
            })

    for row in rows:
        row['is_active'] = bool(row['is_active'])
        row['status_label'] = 'فعال' if row['is_active'] else ('پیش‌نویس' if row['status'] == 'draft' else 'بایگانی‌شده' if row['status'] == 'archived' else 'غیرفعال')
        row['term_label'] = _teacher_semester_label(row['semester'], row['academic_year'])
        row['faces'] = faces.get(str(row['id']), [])
        row['more_students'] = max(0, int(row['students_count'] or 0) - len(row['faces']))
        row['next_exam_label'] = _jalali_long_date(row['next_exam_at'], with_weekday=False)
        row['last_exam_label'] = _jalali_long_date(row['last_exam_at'], with_weekday=False)

    all_own = ' AND '.join(own)
    summary = erd_row(
        f"""
        SELECT COUNT(*) AS classes, SUM(CASE WHEN {is_active} THEN 1 ELSE 0 END) AS active_classes,
               (SELECT COUNT(DISTINCT m.student_user_id) FROM student_group_members m
                 WHERE m.group_id IN (SELECT sg.id FROM student_groups sg WHERE {all_own})) AS students
        FROM student_groups sg WHERE {all_own}
        """,
        [*own_params, *own_params],
    )
    lifecycle = "COALESCE(e.lifecycle_status, '')"
    summary['finished_exams'] = erd_row(
        f"""
        SELECT COUNT(*) AS count FROM exams e
        WHERE e.teacher_id = %s AND {not_cancelled}
          AND ({lifecycle} IN ('closed', 'archived') OR ({lifecycle} IN ('published', 'in_progress') AND e.end_at < %s))
        """,
        [teacher_id, now],
    )['count']
    summary['active_classes'] = summary['active_classes'] or 0
    return {
        'rows': rows, 'page': page, 'total': total, 'query': query, 'term': term, 'status': status,
        'terms': terms, 'filters': TEACHER_CLASS_LIST_FILTERS, 'summary': summary,
        'tabs': [{'key': key, 'label': TEACHER_CLASS_LIST_FILTERS[key], 'count': int(tab_counts[key] or 0),
                  'active': status == key} for key in ('current', 'past')],
    }


TEACHER_RESULTS_PAGE_SIZE = 10
TEACHER_RESULT_BUCKETS = ((0, 4), (4, 8), (8, 12), (12, 16), (16, 20))


def _exam_score_scale(exam) -> float:
    """The exam's «مجموع نمرات کل آزمون» (scores are reported out of it); 20 when the exam does not set one."""
    scale = _sx_float((exam or {}).get('total_score'), 0)
    return scale if scale > 0 else 20.0


def _teacher_owned_exam(teacher_id, exam_id, staff=False):
    """The exam row when it belongs to this teacher, else None (callers turn None into a 404).

    staff=True also admits the exam's «عوامل آزمون» (ناظر / همکار تصحیح / طراح) for viewing its reports;
    row['is_owner'] says whether the teacher may also act on it (e.g. publish results)."""
    staff_sql = " OR e.id IN (SELECT es.exam_id FROM exam_staff es WHERE es.teacher_id = %s)" if staff else ''
    row = erd_row(
        f"""
        SELECT e.id, e.title, e.start_at, e.end_at, e.duration_minutes, e.passing_score, e.teacher_id,
               COALESCE(c.title, '-') AS course, {_exam_result_columns()[0]}
        FROM exams e LEFT JOIN courses c ON c.id = e.course_id
        WHERE e.id = %s AND (e.teacher_id = %s{staff_sql})
        """,
        [exam_id, teacher_id, *([teacher_id] if staff else [])],
    )
    if row:
        row['result_visibility'] = _exam_result_visibility(row)
        row['is_owner'] = str(row['teacher_id']) == str(teacher_id)
    return row


def _teacher_exam_options(teacher_id) -> list:
    """The teacher's exams for the results/monitoring selector, newest first."""
    rows = erd_rows(
        """
        SELECT e.id, e.title, e.start_at, e.end_at,
               (SELECT COUNT(*) FROM exam_attempts ea WHERE ea.exam_id = e.id AND ea.status IN ('submitted', 'graded')) AS submitted,
               (SELECT COUNT(*) FROM exam_attempts ea WHERE ea.exam_id = e.id AND ea.status = 'in_progress') AS in_progress
        FROM exams e
        WHERE (e.teacher_id = %s OR e.id IN (SELECT es.exam_id FROM exam_staff es WHERE es.teacher_id = %s))
          AND COALESCE(e.is_cancelled, false) = false
        ORDER BY CASE WHEN e.start_at IS NULL THEN 1 ELSE 0 END, e.start_at DESC, e.title
        LIMIT 200
        """,
        [teacher_id, teacher_id],  # own exams and exams the teacher is «عوامل آزمون» of
    )
    for row in rows:
        row['start_at'], row['end_at'] = erd_datetime(row['start_at']), erd_datetime(row['end_at'])
        row['date_label'] = _jalali_long_date(row['start_at'])
    return rows


def _teacher_exam_results(exam, page_number, receipt_code='') -> dict:
    """Score summary, 0-20 distribution and one page of submitted attempts for an exam the teacher owns.

    With a «شناسه رسید» only that attempt is listed."""
    from django.core.paginator import Paginator

    has_receipt = erd_has_column('exam_attempts', 'receipt_code')
    # «دقت نمره‌دهی»: scores shown with two decimals or as whole numbers
    digits = 0 if prefs(exam.get('teacher_id')).get('rounding') == 'integer' else 2
    receipt_code = receipt_code if has_receipt else ''

    graded = erd_rows(
        "SELECT score, max_score FROM exam_attempts WHERE exam_id = %s AND status IN ('submitted', 'graded') "
        'AND COALESCE(is_graded, false) = true AND score IS NOT NULL AND max_score > 0',
        [exam['id']],
    )
    summary = erd_row(
        """
        SELECT COUNT(DISTINCT student_id) AS participants, COUNT(*) AS attempts,
               SUM(CASE WHEN COALESCE(is_graded, false) = false OR score IS NULL THEN 1 ELSE 0 END) AS ungraded
        FROM exam_attempts WHERE exam_id = %s AND status IN ('submitted', 'graded')
        """,
        [exam['id']],
    )
    scale = _exam_score_scale(exam)
    scores = [float(row['score']) * scale / float(row['max_score']) for row in graded]
    passed = sum(
        1 for row in graded
        if _sx_result_status({'is_graded': True, 'score': row['score'], 'max_score': row['max_score'],
                              'passing_score': exam.get('passing_score'), 'passing_percent': exam.get('passing_percent'),
                              'percent': _sx_percent(row['score'], row['max_score'])})[0] == 'قبول'
    )
    buckets = []
    for low_part, high_part in TEACHER_RESULT_BUCKETS:  # the 0-20 bands, stretched to the exam's own scale
        low, high = low_part * scale / 20, high_part * scale / 20
        count = sum(1 for score in scores if low <= score < high or (high_part == 20 and score == scale))
        buckets.append({'label': f'{low:g}–{high:g}', 'count': count})
    peak = max((bucket['count'] for bucket in buckets), default=0) or 1
    for bucket in buckets:
        bucket['height'] = round(bucket['count'] * 100 / peak)

    total = summary['attempts'] if summary else 0
    page = Paginator(range(total), TEACHER_RESULTS_PAGE_SIZE).get_page(page_number)
    rows = erd_rows(
        """
        SELECT ea.id, ea.score, ea.max_score, ea.is_graded, ea.submitted_at, {receipt} AS receipt_code,
               COALESCE(NULLIF(p.full_name, ''), p.username, 'دانشجو') AS name,
               COALESCE(NULLIF(sp.student_number, ''), p.identifier, '') AS code
        FROM exam_attempts ea
        JOIN profiles p ON p.id = ea.student_id
        LEFT JOIN student_profiles sp ON sp.user_id = ea.student_id
        WHERE ea.exam_id = %s AND ea.status IN ('submitted', 'graded'){only_receipt}
        ORDER BY CASE WHEN ea.score IS NULL THEN 1 ELSE 0 END, ea.score DESC, name
        LIMIT %s OFFSET %s
        """.format(receipt='ea.receipt_code' if has_receipt else 'NULL',
                   only_receipt=' AND ea.receipt_code = %s' if receipt_code else ''),
        [exam['id'], *([receipt_code] if receipt_code else []), TEACHER_RESULTS_PAGE_SIZE,
         page.start_index() - 1 if total and not receipt_code else 0],
    )
    flags = _attempt_event_counts(row['id'] for row in rows)
    for row in rows:
        row['flags'] = flags.get(str(row['id']))
        row['percent'] = _sx_percent(row['score'], row['max_score'])
        row['score_20'] = round(float(row['score']) * scale / float(row['max_score']), digits) if row['score'] is not None and row['max_score'] else None
        row['status_label'], tone, _pending = _sx_result_status(
            {**row, 'passing_score': exam.get('passing_score'), 'passing_percent': exam.get('passing_percent')})
        row['status_tone'] = {'green': 'is-ok', 'red': 'is-danger'}.get(tone, 'is-warn')
        row['submitted_label'] = _jalali_long_date(row['submitted_at'])
    return {
        'participants': summary['participants'] if summary else 0,
        'ungraded': (summary or {}).get('ungraded') or 0,
        'average': round(sum(scores) / len(scores), digits) if scores else None,
        'highest': round(max(scores), digits) if scores else None,
        'lowest': round(min(scores), digits) if scores else None,
        'pass_rate': round(passed * 100 / len(scores)) if scores else None,
        'scale': f'{scale:g}',
        'buckets': buckets if scores else [],
        'rows': rows,
        'page': page,
    }


def _teacher_exam_monitoring(exam) -> dict:
    """Live counts and in-progress attempts of an exam the teacher owns."""
    now = timezone.now()
    start_at, end_at = erd_datetime(exam.get('start_at')), erd_datetime(exam.get('end_at'))
    counts = erd_row(
        """
        SELECT COUNT(DISTINCT student_id) AS started,
               COUNT(DISTINCT CASE WHEN status = 'in_progress' THEN student_id END) AS in_progress,
               COUNT(DISTINCT CASE WHEN status IN ('submitted', 'graded') THEN student_id END) AS submitted
        FROM exam_attempts WHERE exam_id = %s
        """,
        [exam['id']],
    ) or {}
    assigned = _teacher_dashboard_participant_counts([str(exam['id'])]).get(str(exam['id']))
    rows = erd_rows(
        """
        SELECT ea.id, ea.started_at,
               COALESCE(NULLIF(p.full_name, ''), p.username, 'دانشجو') AS name,
               COALESCE(NULLIF(sp.student_number, ''), p.identifier, '') AS code,
               (SELECT COUNT(*) FROM attempt_answers aa WHERE aa.attempt_id = ea.id AND aa.answer IS NOT NULL) AS answered
        FROM exam_attempts ea
        JOIN profiles p ON p.id = ea.student_id
        LEFT JOIN student_profiles sp ON sp.user_id = ea.student_id
        WHERE ea.exam_id = %s AND ea.status = 'in_progress'
        ORDER BY ea.started_at
        LIMIT 300
        """,
        [exam['id']],
    )
    question_count = erd_count('exam_questions', 'exam_id = %s', [exam['id']])
    flags = _attempt_event_counts(row['id'] for row in rows)
    for row in rows:
        row['flags'] = flags.get(str(row['id']))
        started = erd_datetime(row['started_at'])
        row['started_label'] = timezone.localtime(started).strftime('%H:%M') if started else '-'
        row['elapsed_minutes'] = int((now - started).total_seconds() // 60) if started else None
    is_running = bool(start_at and start_at <= now and (end_at is None or end_at >= now))
    return {
        'assigned': assigned,
        'started': counts.get('started') or 0,
        'in_progress': counts.get('in_progress') or 0,
        'submitted': counts.get('submitted') or 0,
        'not_started': max(0, assigned - (counts.get('started') or 0)) if assigned else None,
        'question_count': question_count,
        'rows': rows,
        'is_running': is_running,
        'has_ended': bool(end_at and end_at < now),
        'remaining_seconds': int((end_at - now).total_seconds()) if is_running and end_at else None,
        'start_label': _jalali_long_date(start_at),
        'time_label': f"{timezone.localtime(start_at).strftime('%H:%M') if start_at else ''}"
                      f"{' تا ' + timezone.localtime(end_at).strftime('%H:%M') if end_at else ''}",
    }


def _query_without_page(request) -> list:
    """The current GET parameters except page, so pagination keeps the filters."""
    return [(key, value) for key, values in request.GET.lists() if key != 'page' for value in values]


def _teacher_modern_context(request, page, **extra):
    teacher_id = getattr(request, 'erd_profile_id', None)
    course_detail = {}
    if page == 'course_detail' and teacher_id:
        from .teacher_class import class_context

        course_detail = class_context(request, teacher_id, extra.get('group_id'))
    question_bank = {}
    if page == 'questions' and teacher_id:
        from .teacher_question_bank import question_bank_context

        question_bank = question_bank_context(request, teacher_id)
    return {
        'page': page,
        'teacher_ui': ui_context(teacher_id, getattr(request, 'erd_role', None) or 'teacher') if teacher_id else {},
        'teacher_default_structure': prefs(teacher_id).get('bank_default_structure', 'independent') if page == 'question_type' and teacher_id else '',
        'teacher_profile': _teacher_modern_profile(request),
        # Only the dashboard shows it; the other numbers it used to carry (with invented fallbacks) were never shown.
        'teacher_stats': {'questions': erd_count('questions', 'teacher_id = %s AND archived_at IS NULL', [teacher_id])} if page == 'dashboard' and teacher_id else {},
        **course_detail,
        'dashboard': _teacher_dashboard_data(teacher_id) if page == 'dashboard' and teacher_id else None,
        'subordinates': _subordinate_overview('teacher', teacher_id) if page == 'dashboard' and teacher_id else None,
        **question_bank,
        **extra,
    }


