def _em_account_label(status):
    if status in {'inactive', 'غیرفعال'}:
        return 'غیرفعال'
    if status in {'blocked', 'مسدود'}:
        return 'مسدود'
    return 'فعال'


def _em_account_tone(status):
    if status in {'inactive', 'غیرفعال'}:
        return 'warn'
    if status in {'blocked', 'مسدود'}:
        return 'bad'
    return 'ok'


