@erd_role_required('academic_manager', 'admin')
def exam_manager_dashboard(request):
    """The academic manager's dashboard, every number limited to the exams of the manager's units."""
    today = timezone.localdate()
    tomorrow = today + timedelta(days=1)
    now = timezone.now()
    profile = getattr(request, 'erd_profile', None) or erd_profile_for_user(request.user) or {}
    display_name = profile.get('full_name') or request.user.get_full_name() or request.user.username
    if _erd_is_admin_request(request):
        cte, cte_params, scope = '', [], '1=1'
    else:
        cte, cte_params, scope = _erd_manager_scope_cte(), [request.erd_profile_id], _erd_exam_scope_condition()

    def scoped_exam_count(where, params=None):
        return _erd_scoped_exam_count(request, where, params or [])

    published = 'COALESCE(e.is_published, false) = true AND COALESCE(e.is_cancelled, false) = false'
    total_exams = _erd_scoped_count(request, 'exams')
    active_exams = scoped_exam_count(published)
    running_exams = scoped_exam_count(f'{published} AND e.start_at <= %s AND (e.end_at IS NULL OR e.end_at >= %s)', [now, now])
    today_exams = scoped_exam_count(
        'e.start_at >= %s AND e.start_at < %s AND COALESCE(e.is_cancelled, false) = false', [today.isoformat(), tomorrow.isoformat()],
    )
    pending_exams = scoped_exam_count("COALESCE(e.lifecycle_status, '') = 'pending_approval' AND COALESCE(e.is_cancelled, false) = false")
    subordinates = _subordinate_overview('admin' if _erd_is_admin_request(request) else 'academic_manager', request.erd_profile_id)
    # the «اساتید» card shows the same numbers as the «زیرمجموعه من» panel below it
    teacher_count, student_count = (next((t['value'] for t in subordinates['tiles'] if t['icon'] == key), 0) for key in ('teachers', 'students'))
    attempts = erd_row(
        f"""
        {cte}
        SELECT SUM(CASE WHEN ea.submitted_at IS NOT NULL AND COALESCE(ea.is_graded, false) = true THEN 1 ELSE 0 END) AS graded,
               SUM(CASE WHEN ea.submitted_at IS NOT NULL AND COALESCE(ea.is_graded, false) = false THEN 1 ELSE 0 END) AS awaiting,
               SUM(CASE WHEN ea.submitted_at IS NULL THEN 1 ELSE 0 END) AS unfinished
        FROM exam_attempts ea JOIN exams e ON e.id = ea.exam_id
        WHERE {scope}
        """,
        cte_params,
    ) or {}
    attempt_items = [
        {'label': 'تصحیح‌شده', 'value': int(attempts.get('graded') or 0), 'color': '#315cff'},
        {'label': 'در انتظار تصحیح', 'value': int(attempts.get('awaiting') or 0), 'color': '#f59e0b'},
        {'label': 'ناتمام (ارسال‌نشده)', 'value': int(attempts.get('unfinished') or 0), 'color': '#ef4444'},
    ]
    pending_answers = int((erd_row(
        f"""
        {cte}
        SELECT COUNT(*) AS n
        FROM attempt_answers aa JOIN exam_attempts ea ON ea.id = aa.attempt_id JOIN exams e ON e.id = ea.exam_id
        WHERE COALESCE(aa.needs_manual_grading, false) = true AND ea.submitted_at IS NOT NULL AND {scope}
        """,
        cte_params,
    ) or {}).get('n') or 0)
    teacher_requests = _manager_pending_teacher_request_count(request)
    exams_url = reverse('core:exam_manager_exams')
    exam_status_items = _exam_status_counts(scope, [], cte, cte_params)
    trend = _attempt_trend(exam_where=scope, cte=cte, cte_params=cte_params)
    context = {
        'display_name': display_name,
        'role_label': 'مدیر آموزشی',
        'dashboard_stats': [
            {'label': 'کل آزمون‌ها', 'value': total_exams, 'hint': f'{active_exams} منتشرشده', 'tone': 'indigo', 'icon': 'doc'},
            {'label': 'آزمون‌های منتشرشده', 'value': active_exams, 'hint': f'{running_exams} در حال برگزاری', 'tone': 'green', 'icon': 'play'},
            {'label': 'آزمون‌های امروز', 'value': today_exams, 'hint': 'با شروع امروز', 'tone': 'orange', 'icon': 'calendar'},
            {'label': 'اساتید', 'value': teacher_count, 'hint': f'{student_count} دانشجو', 'tone': 'emerald', 'icon': 'users'},
            {'label': 'نیازمند بررسی', 'value': pending_exams, 'hint': 'آزمون در انتظار تأیید', 'tone': 'red', 'icon': 'alert'},
            {'label': 'پاسخ‌های در انتظار تصحیح', 'value': pending_answers, 'hint': 'تصحیح دستی استاد', 'tone': 'blue', 'icon': 'message'},
        ],
        'quick_actions': [
            {'label': 'ایجاد آزمون جدید', 'url': reverse('core:exam_manager_exam_create'), 'tone': 'primary', 'icon': 'plus'},
            {'label': 'انتشار آزمون', 'url': reverse('core:exam_manager_active_exams'), 'icon': 'send'},
            {'label': 'مدیریت سوالات', 'url': exams_url, 'icon': 'help'},
            {'label': 'زمان‌بندی آزمون', 'url': reverse('core:exam_manager_calendar'), 'icon': 'calendar'},
            {'label': f'درخواست‌های اساتید ({teacher_requests})', 'url': reverse('core:exam_manager_teacher_requests'), 'icon': 'users'},
        ],
        # Only what has something waiting, each with its count and the page that handles it.
        'attention_items': [
            item for item in (
                {'label': f'{pending_exams} آزمون در انتظار تأیید', 'count': pending_exams, 'url': f'{exams_url}?status=draft', 'color': '#ef4444', 'icon': 'database'},
                {'label': f'{teacher_requests} درخواست تغییر مشخصات استاد', 'count': teacher_requests, 'url': reverse('core:exam_manager_teacher_requests'), 'color': '#3b82f6', 'icon': 'user'},
                {'label': f'{pending_answers} پاسخ در انتظار تصحیح استاد', 'count': pending_answers, 'url': '', 'color': '#f59e0b', 'icon': 'clock'},
            ) if item['count']
        ],
        'exam_status_items': exam_status_items,
        'exam_status_style': _conic_style(exam_status_items),
        'participation_items': attempt_items,
        'participation_total': sum(item['value'] for item in attempt_items),
        'participation_style': _conic_style(attempt_items, 'value'),
        'trend_points': trend['activity_secondary_points'],
        'trend_labels': trend['trend_labels'],
        'trend_submitted_total': trend['trend_submitted_total'],
        'subordinates': subordinates,
    }
    return render(request, 'exam_manager/dashboard.html', context)


# institution_admin_dashboard/institution_users/institution_structure/institution_exams/
# institution_violations each have their own dedicated, correctly-scoped
# @institution_admin_required implementations defined earlier in this file (near
# line 10018+) — do not alias them to super_admin_*/exam_manager_*/teacher_* views
# here, that shadows the real implementations with views gated by unrelated role
# checks (super_admin_required / erd_role_required) that a real institution_admin
# user never satisfies, breaking the whole institution-admin panel with 403s.


# Final modern student exam overrides. URL patterns import the last bound names,
# so these definitions take precedence over the older legacy/ERD fallbacks above.
def _sx_dt(value):
    if not value:
        return None
    if isinstance(value, datetime):
        return value if timezone.is_aware(value) else _db_naive_datetime(value)
    text = str(value).replace('Z', '+00:00')
    try:
        dt = datetime.fromisoformat(text)
        return dt if timezone.is_aware(dt) else timezone.make_aware(dt, timezone.get_current_timezone())
    except ValueError:
        return None


def _sx_json(value, fallback=None):
    if value in (None, ''):
        return fallback
    if isinstance(value, (dict, list)):
        return value
    try:
        return json.loads(value)
    except (TypeError, ValueError):
        return fallback


def _sx_answer_value(value):
    parsed = _sx_json(value, value)
    if isinstance(parsed, dict):
        parsed = parsed.get('value') or parsed.get('answer') or parsed.get('text') or parsed.get('selected')
    if isinstance(parsed, list):
        parsed = parsed[0] if parsed else ''
    return '' if parsed is None else str(parsed)


def _sx_question_options(value, kind='single'):
    parsed = _sx_json(value, None)
    if kind == 'true_false' and not parsed:
        parsed = ['درست', 'نادرست']
    if not parsed:
        return []
    if isinstance(parsed, dict):
        parsed = parsed.get('options') or parsed.get('choices') or list(parsed.values())
    options = []
    for index, item in enumerate(parsed or [], start=1):
        if isinstance(item, dict):
            label = item.get('label') or item.get('text') or item.get('title') or item.get('value') or str(index)
            value = item.get('value') or item.get('id') or label
        else:
            label = item
            value = item
        option = {'label': str(label), 'value': str(value)}
        if isinstance(item, dict):
            option.update(_sx_media_fields(item.get('media')))
        options.append(option)
    return options


def _sx_media_fields(url, prefix=''):
    """Expose only media uploaded through the question builder (never arbitrary stored URLs)."""
    url = str(url or '').strip()
    if not url.startswith(f'{settings.MEDIA_URL}question-media/') or '..' in url:
        return {}
    return {f'{prefix}media': url, f'{prefix}media_kind': _media_kind(url)}


def _sx_question_media(value):
    media = _sx_json(value, {}) or {}
    if not isinstance(media, dict):
        return {}
    result = {}
    for kind in ('image', 'audio', 'video'):
        if _sx_media_fields(media.get(kind)):
            result[kind] = media[kind]
    if result:
        result['image_alt'] = media.get('image_alt') or ''
        result['video_caption'] = media.get('video_caption') or ''
        result['video_subtitle'] = (media.get('video_subtitle') or '') if result.get('video') else ''
    return result


def _sx_item_token(attempt_id, question_id, value):
    """Opaque per-attempt id of an ordering item or matching answer: the page must not carry the real index,
    since the correct ordering is always 1,2,…,n and the correct matching always i:i."""
    return 't' + salted_hmac('exam-item-token', f'{attempt_id}:{question_id}:{value}').hexdigest()[:12]  # never all digits


def _sx_token_item_values(kind, row):
    """The real values the tokens of an ordering/matching question stand for."""
    if kind == 'ordering':
        return [item['value'] for item in _sx_ordering_display_items(row.get('ordering_items'), row['question_id'])]
    return [item['value'] for item in _sx_matching_display_columns(row.get('matching_pairs'), row['question_id'], row.get('scoring_settings'))[1]]


def _sx_encode_item_answer(kind, row, attempt_id, answer):
    """A saved answer ('3,1,2' / '1:2,2:d1') with its real values swapped for this attempt's tokens."""
    token = lambda value: _sx_item_token(attempt_id, row['question_id'], value)
    parts = [part.strip() for part in str(answer or '').split(',') if part.strip()]
    if kind == 'ordering':
        return ','.join(token(part) for part in parts)
    return ','.join(f'{left}:{token(right)}' for left, _, right in (part.partition(':') for part in parts) if right)


def _sx_decode_item_answer(kind, row, attempt_id, posted):
    """Back from tokens to real values; anything that is not one of this attempt's tokens is dropped."""
    by_token = {_sx_item_token(attempt_id, row['question_id'], value): value for value in _sx_token_item_values(kind, row)}
    parts = [part.strip() for part in str(posted or '').split(',') if part.strip()]
    if kind == 'ordering':
        return ','.join(by_token[part] for part in parts if part in by_token)
    return ','.join(f'{left}:{by_token[right]}' for left, _, right in (part.partition(':') for part in parts) if right in by_token)


def _sx_ordering_display_items(value, question_id, attempt_id=None):
    parsed = _sx_json(value, None) or []
    items = []
    for index, entry in enumerate(parsed, start=1):
        if isinstance(entry, dict):
            text = entry.get('text') or entry.get('label') or ''
            order = entry.get('order') or index
        else:
            text = str(entry)
            order = index
        if text:
            items.append({'value': str(order), 'label': text, **(_sx_media_fields(entry.get('media')) if isinstance(entry, dict) else {})})
    if attempt_id:  # the exam page: tokens instead of positions, and an order of its own per attempt
        for item in items:
            item['value'] = _sx_item_token(attempt_id, question_id, item['value'])
        random.Random(f'{attempt_id}-{question_id}').shuffle(items)
    else:
        random.Random(str(question_id)).shuffle(items)
    return items


def _sx_matching_display_columns(value, question_id, scoring_settings=None, attempt_id=None):
    parsed = _sx_json(value, None) or []
    settings_data = _sx_json(scoring_settings, {}) or {}
    settings_data = settings_data if isinstance(settings_data, dict) else {}
    many_to_one = settings_data.get('matching_mode') == 'many_to_one'
    left_items = []
    right_items = []
    seen_right = set()
    for index, pair in enumerate(parsed, start=1):
        if not isinstance(pair, dict):
            continue
        left = pair.get('left') or ''
        right = pair.get('right') or ''
        if not (left and right):
            continue
        left_items.append({'value': str(index), 'label': left, **_sx_media_fields(pair.get('left_media'))})
        right_key = _normalize_answer_text(right)
        if many_to_one and right_key in seen_right:
            # Shared answers appear once; grading compares the right-hand text, so any pair index with it is correct.
            continue
        seen_right.add(right_key)
        right_items.append({'value': str(index), 'label': right, **_sx_media_fields(pair.get('right_media'))})
    for index, distractor in enumerate(settings_data.get('matching_distractors') or [], start=1):
        if str(distractor).strip():
            right_items.append({'value': f'd{index}', 'label': str(distractor).strip()})
    if attempt_id:  # the exam page: right-hand answers as tokens, in an order of its own per attempt
        for item in right_items:
            item['value'] = _sx_item_token(attempt_id, question_id, item['value'])
        random.Random(f'{attempt_id}-{question_id}-right').shuffle(right_items)
    else:
        random.Random(f'{question_id}-right').shuffle(right_items)
    return left_items, right_items


_BLANK_MARKER_RE = re.compile(r'\[[۰۱۲۳۴۵۶۷۸۹0-9]+\]')


def _sx_fill_blank_segments(text):
    parts = _BLANK_MARKER_RE.split(text or '')
    markers = _BLANK_MARKER_RE.findall(text or '')
    segments = []
    for index, part in enumerate(parts):
        if part:
            segments.append({'kind': 'text', 'value': part})
        if index < len(markers):
            segments.append({'kind': 'blank', 'index': index + 1})
    return segments


_HTML_TAG_RE = re.compile(r'(<[^>]*>)')


def _fill_blank_stem_html(scoring_settings, text, question_id, answers):
    """Rich fill-blank stem with an answer input in place of each [n] marker.

    Markers are only replaced in text between tags (never inside an attribute). If the rich HTML does not
    hold exactly the markers of the plain `text` (e.g. a marker split by formatting), returns '' so the
    page falls back to the plain-text segments, which grading is based on.
    """
    html = _question_stem_html(scoring_settings)
    expected = len(_BLANK_MARKER_RE.findall(text or ''))
    if not html or not expected:
        return ''
    parts = _HTML_TAG_RE.split(html)
    if sum(len(_BLANK_MARKER_RE.findall(part)) for part in parts if not part.startswith('<')) != expected:
        return ''
    counter = iter(range(1, expected + 1))

    def blank_input(_match):
        number = next(counter)
        value = answers[number - 1] if number <= len(answers) else ''
        return format_html(
            '<input class="qx-blank" type="text" name="answer_{}" value="{}" aria-label="جای خالی {}" placeholder="{}" autocomplete="off">',
            question_id, value, number, number,
        )

    return ''.join(part if part.startswith('<') else _BLANK_MARKER_RE.sub(blank_input, part) for part in parts)


def _sx_type_label(kind):
    return {
        'single': 'چهارگزینه‌ای',
        'single_choice': 'چهارگزینه‌ای',
        'multiple_choice': 'چهارگزینه‌ای',
        'multi': 'چندپاسخی',
        'true_false': 'درست یا نادرست',
        'essay': 'تشریحی',
        'descriptive': 'تشریحی',
        'short_answer': 'پاسخ کوتاه',
        'fill_blank': 'جای خالی',
        'matching': 'تطبیقی',
        'ordering': 'مرتب‌سازی',
        **question_kinds.TYPE_LABELS,
    }.get(kind or '', kind or 'سوال')


def _sx_student_context(request):
    profile = getattr(request, 'erd_profile', None) or erd_profile_for_user(request.user) or {}
    student_profile = erd_row(
        """
        SELECT user_id AS id, user_id AS pk, student_number, field_of_study, degree, semester
        FROM student_profiles
        WHERE user_id = %s
        """,
        [request.erd_profile_id],
    ) or {}
    student_profile['profile'] = {
        'full_name': profile.get('full_name') or request.user.get_full_name() or request.user.username,
        'avatar_url': profile.get('avatar_url') or '',
    }
    student_profile.setdefault('pk', request.erd_profile_id)
    student_profile.setdefault('student_number', profile.get('identifier') or request.erd_profile_id)
    return student_profile


def _sx_exam_row(exam_id, student_id):
    has_last_entry = erd_has_column('exams', 'last_entry_at')
    last_entry = 'e.last_entry_at' if has_last_entry else 'NULL'
    last_entry_group = ', e.last_entry_at' if has_last_entry else ''
    has_guide = erd_has_column('exams', 'guidance_file_url')
    guide = 'e.guidance_file_url' if has_guide else 'NULL'
    last_entry_group += ', e.guidance_file_url' if has_guide else ''
    mode = _sx_exam_mode_sql()
    last_entry_group += ', e.exam_mode, e.max_attempts' if erd_has_column('exams', 'exam_mode') else ', e.max_attempts'
    rows = erd_rows(
        f"""
        SELECT e.id AS pk, e.id, e.title, COALESCE(e.description, '') AS description,
               e.start_at, e.end_at, COALESCE(e.duration_minutes, 90) AS duration_minutes,
               COALESCE(e.passing_score, 60) AS passing_score,
               COALESCE(e.lifecycle_status, '') AS lifecycle_status,
               COALESCE(e.exam_type, 'آنلاین') AS exam_type,
               COALESCE(c.title, 'درس') AS course_title,
               COALESCE(p.full_name, 'استاد') AS teacher_name,
               {last_entry} AS last_entry_at, {guide} AS guidance_file_url,
               {mode} AS exam_mode, e.max_attempts,
               COUNT(eq.id) AS question_count
        FROM exams e
        LEFT JOIN courses c ON c.id = e.course_id
        LEFT JOIN profiles p ON p.id = e.teacher_id
        LEFT JOIN exam_questions eq ON eq.exam_id = e.id
        WHERE e.id = %s AND {_erd_student_exam_access_condition()}
        GROUP BY e.id, e.title, e.description, e.start_at, e.end_at, e.duration_minutes,
                 e.passing_score, e.lifecycle_status, e.exam_type, c.title, p.full_name{last_entry_group}
        LIMIT 1
        """,
        [exam_id, student_id, student_id, student_id],
    )
    if not rows:
        # Outside the access rule a student still reaches an exam they already have an attempt on
        # (e.g. it was unpublished mid-attempt); any other exam id is not theirs.
        rows = erd_rows(
            f"""
            SELECT e.id AS pk, e.id, e.title, COALESCE(e.description, '') AS description,
                   e.start_at, e.end_at, COALESCE(e.duration_minutes, 90) AS duration_minutes,
                   COALESCE(e.passing_score, 60) AS passing_score,
                   COALESCE(e.lifecycle_status, '') AS lifecycle_status,
                   COALESCE(e.exam_type, 'آنلاین') AS exam_type,
                   COALESCE(c.title, 'درس') AS course_title,
                   COALESCE(p.full_name, 'استاد') AS teacher_name,
                   {last_entry} AS last_entry_at, {guide} AS guidance_file_url,
                   {mode} AS exam_mode, e.max_attempts,
                   COUNT(eq.id) AS question_count
            FROM exams e
            LEFT JOIN courses c ON c.id = e.course_id
            LEFT JOIN profiles p ON p.id = e.teacher_id
            LEFT JOIN exam_questions eq ON eq.exam_id = e.id
            WHERE e.id = %s
              AND EXISTS (SELECT 1 FROM exam_attempts own WHERE own.exam_id = e.id AND own.student_id = %s)
            GROUP BY e.id, e.title, e.description, e.start_at, e.end_at, e.duration_minutes,
                     e.passing_score, e.lifecycle_status, e.exam_type, c.title, p.full_name{last_entry_group}
            LIMIT 1
            """,
            [exam_id, student_id],
        )
    if not rows:
        return None
    row = rows[0]
    row['starts_at'] = _sx_dt(row.get('start_at')) or timezone.now()
    row['duration_minutes'] = _em_int(row.get('duration_minutes'), 90)
    row['ends_at'] = _sx_dt(row.get('end_at')) or (row['starts_at'] + timedelta(minutes=row['duration_minutes']))
    # «آخرین زمان ورود»: new attempts may not start after it, even while the exam is still running.
    last_entry = _sx_dt(row.get('last_entry_at'))
    row['entry_ends_at'] = min(row['ends_at'], last_entry) if last_entry else row['ends_at']
    row['question_count'] = _em_int(row.get('question_count'), 0)
    rules = _sx_exam_rules(exam_id)
    row['rules'] = rules
    # «پایان دسترسی»: after it nobody enters or answers; «شروع دسترسی»: the entry page (rules, identity) opens then.
    access_end = _sx_dt(rules['registration_end_at'])
    if access_end:
        row['ends_at'] = min(row['ends_at'], access_end)
        row['entry_ends_at'] = min(row['entry_ends_at'], access_end)
    row['access_starts_at'] = _sx_dt(rules['registration_start_at'])
    row['needs_entry'] = rules['settings_enforced'] and (rules['show_instructions_before_start'] or rules['identity_verification_required'])
    row['code'] = exam_access_code(row['id'])
    row['total_score'] = _exam_score_scale(erd_row('SELECT total_score FROM exams WHERE id = %s', [exam_id])
                                           if erd_has_column('exams', 'total_score') else None)
    cover = erd_row('SELECT cover_image_url FROM exams WHERE id = %s', [exam_id]) if erd_has_column('exams', 'cover_image_url') else None
    row['cover_image_url'] = (cover or {}).get('cover_image_url') or ''  # the wizard's «تصویر کاور»
    return row


def _sx_exam_rule_lines(exam) -> list:
    """The exam's rules in words for its detail and entry pages, from its real settings."""
    rules = exam['rules']
    lines = [f"مدت آزمون {exam['duration_minutes']} دقیقه است و پس از شروع، زمان متوقف نمی‌شود."]
    if exam.get('last_entry_at'):
        lines.append(f"آخرین زمان ورود به آزمون ساعت {timezone.localtime(exam['entry_ends_at']):%H:%M} است.")
    if rules['max_attempts'] == 0:
        lines.append('تعداد دفعات شرکت در این آزمون محدود نیست.')
    elif rules['max_attempts'] > 1:
        lines.append(f"می‌توانید حداکثر {rules['max_attempts']} بار در این آزمون شرکت کنید.")
    lines.append('سؤال‌ها یکی‌یکی نمایش داده می‌شوند.' if rules['one_question_per_page'] else 'همه‌ی سؤال‌ها در یک صفحه نمایش داده می‌شوند.')
    if not rules['review_answers_enabled']:
        lines.append('بازگشت به سؤال‌های قبلی ممکن نیست.')
    if not rules['allow_answer_changes']:
        lines.append('پاسخ هر سؤال پس از رفتن به سؤال دیگر قابل تغییر نیست.')
    lines.append('در پایان زمان، پاسخ‌های ذخیره‌شده خودکار ارسال می‌شوند.' if rules['auto_submit_on_time_end']
                 else 'در پایان زمان، پاسخ‌ها خودکار ارسال نمی‌شوند؛ پیش از تمام شدن زمان «پایان آزمون» را بزنید.')
    if rules['device_limit_enabled']:
        lines.append('آزمون در هر لحظه فقط روی یک دستگاه قابل پاسخ‌گویی است.')
    if rules['fullscreen_required']:
        lines.append('آزمون در حالت تمام‌صفحه برگزار می‌شود و خروج از آن ثبت می‌شود.')
    if rules['track_tab_exit']:
        lines.append('خروج از صفحه‌ی آزمون یا رفتن به تب دیگر برای استاد ثبت می‌شود.')
    if rules['copy_paste_prevention']:
        lines.append('کپی و چسباندن متن در صفحه‌ی آزمون مجاز نیست.')
    if rules['screenshot_prevention']:
        lines.append('گرفتن تصویر یا چاپ صفحه‌ی آزمون مجاز نیست و تلاش برای آن ثبت می‌شود.')
    if rules['webcam_monitoring'] or rules['mic_monitoring']:
        device = 'دوربین و میکروفون' if rules['webcam_monitoring'] and rules['mic_monitoring'] else ('دوربین' if rules['webcam_monitoring'] else 'میکروفون')
        lines.append(f'{device} باید در تمام مدت آزمون روشن باشد؛ قطع آن برای استاد ثبت می‌شود (چیزی ضبط نمی‌شود).')
    if rules['ip_restriction_enabled']:
        lines.append('شرکت در آزمون فقط از شبکه‌ی تعیین‌شده توسط استاد ممکن است.')
    if rules['identity_verification_required']:
        lines.append('پیش از شروع، کد ملی یا شماره دانشجویی خود را وارد کنید.')
    if rules['internet_disconnect_policy'] == 'pause':
        lines.append('اگر اتصال اینترنت قطع شود، پاسخ‌گویی تا وصل شدن دوباره متوقف می‌شود (زمان آزمون ادامه دارد).')
    elif rules['internet_disconnect_policy'] == 'resume_from_last_save':
        lines.append('اگر اتصال اینترنت قطع شود، پاسخ‌ها روی دستگاه شما نگه داشته و پس از اتصال ارسال می‌شوند.')
    return lines


PRACTICE_EXAM_MODE = 'practice'
TRAINING_EXAM_MODE = 'training'  # «آزمون تمرینی»: a course-style exam whose results are released on grading


def _sx_exam_mode_sql(alias='e'):
    """The exam's wizard «نوع آزمون» as SQL; 'standard' where the column does not exist yet."""
    return f"COALESCE({alias}.exam_mode, 'standard')" if erd_has_column('exams', 'exam_mode') else "'standard'"


def _sx_accessible_exams(student_id, practice=False):
    """The student's exams: course exams by default, or only practice exams («آزمون آزمایشی») with practice=True.

    Practice exams have their own section and never count towards the student's results, so the two lists never mix."""
    mode = _sx_exam_mode_sql()
    tags = 'e.tags' if erd_has_column('exams', 'tags') else 'NULL'
    rows = erd_rows(
        f"""
        SELECT e.id AS pk, e.id, e.title, COALESCE(e.description, '') AS description,
               e.start_at, e.end_at, COALESCE(e.duration_minutes, 90) AS duration_minutes,
               COALESCE(e.passing_score, 60) AS passing_score,
               COALESCE(c.title, 'درس') AS course_title, e.course_id, e.academic_year, e.semester,
               e.max_attempts, {tags} AS tags,
               COUNT(eq.id) AS question_count
        FROM exams e
        LEFT JOIN courses c ON c.id = e.course_id
        LEFT JOIN exam_questions eq ON eq.exam_id = e.id
        WHERE {_erd_student_exam_access_condition()}
          AND {mode} {'=' if practice else '<>'} '{PRACTICE_EXAM_MODE}'
        GROUP BY e.id, e.title, e.description, e.start_at, e.end_at, e.duration_minutes, e.passing_score, c.title,
                 e.course_id, e.academic_year, e.semester, e.max_attempts{', e.tags' if tags != 'NULL' else ''}
        ORDER BY e.start_at ASC NULLS LAST, e.title
        LIMIT 80
        """,
        [student_id, student_id, student_id],
    )
    for row in rows:
        row['starts_at'] = _sx_dt(row.get('start_at')) or timezone.now()
        row['duration_minutes'] = _em_int(row.get('duration_minutes'), 90)
        row['ends_at'] = _sx_dt(row.get('end_at')) or (row['starts_at'] + timedelta(minutes=row['duration_minutes']))
        row['question_count'] = _em_int(row.get('question_count'), 0)
    return rows


def _sx_attempt_for_exam(exam_id, student_id):
    return erd_row(
        """
        SELECT id AS pk, id, exam_id, student_id, started_at, submitted_at, score, max_score, status
        FROM exam_attempts
        WHERE exam_id = %s AND student_id = %s
        ORDER BY started_at DESC NULLS LAST
        LIMIT 1
        """,
        [exam_id, student_id],
    )


def _sx_attempt_rows(attempt_id, student_id):
    marked_sql = 'COALESCE(aa.marked_for_review, false) AS marked' if erd_has_column('attempt_answers', 'marked_for_review') else 'false AS marked'
    if erd_has_column('attempt_answers', 'answer_files'):
        marked_sql += ', aa.answer_files'
    optional_sql = ', '.join(
        f'q.{column}' if erd_has_column('questions', column) else f'NULL AS {column}'
        # accepted_answers carries per-blank media hints; only the hints reach the template, never the answers.
        for column in ('matching_pairs', 'ordering_items', 'question_media', 'scoring_settings', 'suggested_time_seconds', 'accepted_answers')
    )
    shuffle_sql = ', '.join(
        f'COALESCE(e.{column}, false) AS exam_{column}' if erd_has_column('exams', column) else f'false AS exam_{column}'
        for column in ('shuffle_questions', 'shuffle_options', 'track_tab_exit', 'fullscreen_required')
    )
    rows = erd_rows(
        f"""
        SELECT ea.id AS attempt_id, ea.exam_id, ea.started_at, ea.submitted_at, ea.status, {_sx_attempt_extra_sql()} AS extra_minutes,
               e.title AS exam_title, COALESCE(e.duration_minutes, 90) AS duration_minutes, e.end_at AS exam_end_at,
               q.id AS question_id, q.text, COALESCE(q.type, 'single') AS type, q.options,
               COALESCE(eq.points, q.default_points) AS question_points,
               {optional_sql},
               aa.answer, {marked_sql}, {shuffle_sql}
        FROM exam_attempts ea
        JOIN exams e ON e.id = ea.exam_id
        JOIN exam_questions eq ON eq.exam_id = e.id
        JOIN questions q ON q.id = eq.question_id
        LEFT JOIN attempt_answers aa ON aa.attempt_id = ea.id AND aa.question_id = q.id
        WHERE ea.id = %s AND ea.student_id = %s
        ORDER BY eq.order_index NULLS LAST, q.id
        """,
        [attempt_id, student_id],
    )
    if rows and rows[0].get('exam_shuffle_questions'):
        # The exam's «ترتیب تصادفی سؤال‌ها»: an order of its own per attempt, the same on every page load.
        random.Random(f'{attempt_id}-questions').shuffle(rows)
    return rows


# The exam wizard's attempt settings, with the value an exam gets when it never set one (older exams and exams made
# outside the wizard). Those defaults are the behaviour exams had before the settings took effect.
EXAM_RULE_DEFAULTS = {
    'review_answers_enabled': True,      # «امکان بازگشت به سوال قبلی»
    'allow_answer_changes': True,        # «امکان تغییر پاسخ»
    'one_question_per_page': True,       # «نمایش یک سوال در هر صفحه»
    'show_question_list': True,          # «نمایش فهرست سوالات»
    'allow_flagging_questions': True,    # «امکان علامت‌گذاری سوال»
    'auto_submit_on_time_end': True,     # «ارسال خودکار در پایان زمان»
    'autosave_enabled': True,            # «ذخیره خودکار پاسخ‌ها»
    'autosave_interval_seconds': 0,      # 0: save shortly after each change
    'copy_paste_prevention': False,
    'screenshot_prevention': False,
    'webcam_monitoring': False,
    'mic_monitoring': False,
    'ip_restriction_enabled': False,
    'ip_restriction_range': '',
    'identity_verification_required': False,
    'device_limit_enabled': True,        # «محدودیت دستگاه»: one device at a time
    'internet_disconnect_policy': 'none',
    'show_instructions_before_start': False,
    'track_tab_exit': False,
    'fullscreen_required': False,
    'registration_start_at': None,       # «شروع دسترسی»
    'registration_end_at': None,         # «پایان دسترسی»
    'end_at': None,
    'max_attempts': 1,
    'exam_mode': 'standard',
}
INTERNET_DISCONNECT_POLICIES = {'resume_from_last_save', 'pause', 'none'}


# Settings every exam has always honoured, wizard-saved or not.
ALWAYS_HONOURED_RULES = {'track_tab_exit', 'fullscreen_required', 'end_at', 'max_attempts', 'exam_mode'}


def _sx_exam_rules(exam_id) -> dict:
    """The exam's attempt settings (EXAM_RULE_DEFAULTS for every value the exam does not set).

    Only an exam whose settings were saved through the wizard (settings_enforced) has them applied: the settings
    columns carry defaults (camera on, …) that every other exam has too, without anyone having chosen them."""
    present = [column for column in EXAM_RULE_DEFAULTS if erd_has_column('exams', column)]
    if erd_has_column('exams', 'settings_enforced'):
        present.append('settings_enforced')
    row = erd_row(f"SELECT {', '.join(present)} FROM exams WHERE id = %s", [exam_id]) if present else None
    rules = dict(EXAM_RULE_DEFAULTS)
    enforced = bool((row or {}).pop('settings_enforced', None)) if row else False
    rules['settings_enforced'] = enforced
    for column, value in (row or {}).items():
        if value is None or (not enforced and column not in ALWAYS_HONOURED_RULES):
            continue
        default = EXAM_RULE_DEFAULTS[column]
        if isinstance(default, bool):
            rules[column] = value in (True, 1, '1', 'true', 't')
        elif isinstance(default, int):
            rules[column] = _em_int(value, default)
        else:
            rules[column] = value
    if rules['internet_disconnect_policy'] not in INTERNET_DISCONNECT_POLICIES:
        rules['internet_disconnect_policy'] = 'none'
    rules['autosave_interval_seconds'] = min(max(rules['autosave_interval_seconds'], 0), 300)
    return rules


def _sx_exam_cutoff(end_at, registration_end_at=None):
    """The moment answering stops for everyone: the exam's end or «پایان دسترسی», whichever comes first."""
    moments = [moment for moment in (_sx_dt(end_at), _sx_dt(registration_end_at)) if moment]
    return min(moments) if moments else None


def _sx_ip_allowed(request, rules) -> bool:
    """«محدودیت IP»: the student's address is inside one of the exam's ranges (an invalid range admits no one)."""
    if not rules.get('ip_restriction_enabled'):
        return True
    import ipaddress

    try:
        address = ipaddress.ip_address(_sx_trusted_client_ip(request))
    except ValueError:
        return False
    return any(address in network for network in _parse_ip_networks(rules.get('ip_restriction_range')))


def _sx_trusted_client_ip(request) -> str:
    """The student's address for an access rule, which must not be forgeable.

    X-Forwarded-For's first entry comes from the browser, so it is not used. Behind the site's nginx (deploy/),
    the connection comes from a local address and X-Real-IP is set by nginx itself; otherwise the connection's
    own address is the student's."""
    import ipaddress

    remote = (request.META.get('REMOTE_ADDR') or '').strip()
    try:
        via_local_proxy = ipaddress.ip_address(remote).is_loopback or ipaddress.ip_address(remote).is_private
    except ValueError:
        via_local_proxy = False
    real_ip = (request.META.get('HTTP_X_REAL_IP') or '').strip()
    return real_ip if via_local_proxy and real_ip else remote


PAGE_RULE_KEYS = (
    'review_answers_enabled', 'allow_answer_changes', 'one_question_per_page', 'show_question_list', 'allow_flagging_questions',
    'auto_submit_on_time_end', 'autosave_enabled', 'autosave_interval_seconds', 'copy_paste_prevention', 'screenshot_prevention',
    'webcam_monitoring', 'mic_monitoring', 'ip_restriction_enabled', 'device_limit_enabled', 'internet_disconnect_policy',
)


def _sx_attempt_page_rules(attempt_id, student_id, exam_id) -> dict:
    """The exam's rules for its attempt page. A practice attempt keeps the practice section's own behaviour
    (one question per page, free navigation, its own connection handling), whatever the wizard said."""
    from . import student_practice as practice

    rules = _sx_exam_rules(exam_id)
    if practice.attempt_practice_mode(attempt_id, student_id):
        rules.update({key: EXAM_RULE_DEFAULTS[key] for key in PAGE_RULE_KEYS})
        rules['is_practice'] = True
    if not rules['review_answers_enabled']:
        rules['one_question_per_page'] = True  # forward-only needs the questions one at a time
    return rules


def _sx_furthest_question(attempt_id) -> int:
    if not erd_has_column('exam_attempts', 'furthest_question'):
        return 1
    row = erd_row('SELECT furthest_question FROM exam_attempts WHERE id = %s', [attempt_id])
    return max(_em_int((row or {}).get('furthest_question'), 1), 1)


def _sx_set_furthest_question(attempt_id, index) -> None:
    if erd_has_column('exam_attempts', 'furthest_question'):
        erd_execute('UPDATE exam_attempts SET furthest_question = %s WHERE id = %s AND COALESCE(furthest_question, 1) < %s',
                    [index, attempt_id, index])


QUESTION_SNIPPET_CHARS = 40


def _sx_question_snippet(item):
    """The start of a question's text for the exam page's question list (blank markers [n] shown as «…»)."""
    text = re.sub(r'\[\d+\]', '…', str(item.get('text') or ''))
    text = ' '.join(text.split())
    if len(text) > QUESTION_SNIPPET_CHARS:
        text = text[:QUESTION_SNIPPET_CHARS].rstrip() + '…'
    return text or item.get('type_label') or ''


def _sx_answer_dashboard(items, current_index):
    total = len(items)
    answered = sum(1 for item in items if item.get('answered'))
    return {
        'items': [
            {
                'index': item['index'],
                'answered': item.get('answered'),
                'marked': item.get('marked'),
                'current': item['index'] == current_index,
                'snippet': _sx_question_snippet(item),
                'type_label': item.get('type_label'),
            }
            for item in items
        ],
        'progress_percent': round(answered * 100 / max(total, 1)),
    }


# Extra seconds after the exam timer hits zero, so the browser's final autosave/auto-submit still lands.
ATTEMPT_GRACE_SECONDS = 60


def _sx_attempt_ends_at(started_at, duration_minutes, exam_end_at, extra_minutes=0):
    """When an attempt's time runs out: start + exam duration (90 minutes when unset), but never after the exam's end.

    extra_minutes («افزودن زمان» on the live monitor, exam_attempts.extra_minutes) lengthens both the attempt and,
    for this attempt only, the exam's end."""
    extra = timedelta(minutes=max(_em_int(extra_minutes, 0), 0))
    ends_at = started_at + timedelta(minutes=_em_int(duration_minutes, 90)) + extra
    exam_end = _sx_dt(exam_end_at)
    return min(ends_at, exam_end + extra) if exam_end else ends_at


def _sx_attempt_extra_sql(alias='ea'):
    """SELECT expression of an attempt's «افزودن زمان» minutes (0 before migration 0064)."""
    return f'COALESCE({alias}.extra_minutes, 0)' if erd_has_column('exam_attempts', 'extra_minutes') else '0'


def _sx_attempt_accepts_answers(attempt_id):
    """True while the attempt is in progress, not submitted, its exam not cancelled, and within its time limit (plus grace).

    The limit matches the exam page timer (_sx_attempt_ends_at).
    """
    attempt = erd_row(
        f"""
        SELECT ea.submitted_at, ea.status, ea.started_at, ea.exam_id, COALESCE(e.duration_minutes, 90) AS duration_minutes,
               e.end_at, COALESCE(e.is_cancelled, false) AS is_cancelled, {_sx_attempt_extra_sql()} AS extra_minutes
        FROM exam_attempts ea
        JOIN exams e ON e.id = ea.exam_id
        WHERE ea.id = %s
        """,
        [attempt_id],
    )
    if not attempt or attempt.get('submitted_at') or (attempt.get('status') or 'in_progress') != 'in_progress':
        return False
    if attempt.get('is_cancelled'):
        return False
    started_at = _sx_dt(attempt.get('started_at'))
    if not started_at:
        return True
    rules = _sx_exam_rules(attempt['exam_id'])
    cutoff = _sx_exam_cutoff(attempt.get('end_at'), rules['registration_end_at'])
    deadline = _sx_attempt_ends_at(started_at, attempt.get('duration_minutes'), cutoff, attempt.get('extra_minutes'))         + timedelta(seconds=ATTEMPT_GRACE_SECONDS)
    return timezone.now() <= deadline


def _sx_attempt_device(request, attempt_id) -> str:
    """'ok' when this browser session may work the attempt (binding a not-yet-bound attempt to it), else 'other'.

    One attempt is answered from one device: another session must take it over explicitly (_sx_take_over_attempt).
    The exam's «محدودیت دستگاه» off lets any of the student's sessions work it."""
    if not erd_has_column('exam_attempts', 'active_session_key'):
        return 'ok'
    attempt = erd_row('SELECT exam_id FROM exam_attempts WHERE id = %s', [attempt_id])
    if attempt and not _sx_exam_rules(attempt['exam_id'])['device_limit_enabled']:
        return 'ok'
    if not request.session.session_key:
        request.session.save()
    key = request.session.session_key
    erd_execute('UPDATE exam_attempts SET active_session_key = %s WHERE id = %s AND active_session_key IS NULL', [key, attempt_id])
    row = erd_row('SELECT active_session_key FROM exam_attempts WHERE id = %s', [attempt_id])
    return 'ok' if (row or {}).get('active_session_key') == key else 'other'


def _sx_take_over_attempt(request, attempt_id):
    """Move the attempt to this session; the previous device can no longer save. The teacher sees it in the log."""
    if not request.session.session_key:
        request.session.save()
    erd_execute('UPDATE exam_attempts SET active_session_key = %s WHERE id = %s AND submitted_at IS NULL', [request.session.session_key, attempt_id])
    _log_attempt_event(request, attempt_id, 'attempt_device_takeover', 'آزمون دانشجو روی دستگاه دیگری ادامه یافت.')


def _sx_locked_question_ids(attempt_id) -> set:
    """Questions whose answer no longer changes: practice-tutorial feedback was shown, or the exam's
    «امکان تغییر پاسخ» is off and the student left the answered question (locked_at)."""
    conditions = [f'{column} IS NOT NULL' for column in ('feedback_shown_at', 'locked_at') if erd_has_column('attempt_answers', column)]
    if not conditions:
        return set()
    return {
        str(row['question_id'])
        for row in erd_rows(f"SELECT question_id FROM attempt_answers WHERE attempt_id = %s AND ({' OR '.join(conditions)})", [attempt_id])
    }


def _sx_clear_attempt_answers(attempt_id) -> int:
    """«پاک کردن همه‌ی پاسخ‌ها» on the exam page: every answer, answer file and review mark of the attempt is cleared,
    except answers that no longer change (_sx_locked_question_ids). The exam time is not touched. Returns the count."""
    locked = _sx_locked_question_ids(attempt_id)
    has_files = erd_has_column('attempt_answers', 'answer_files')
    has_mark = erd_has_column('attempt_answers', 'marked_for_review')
    rows = erd_rows(
        f"SELECT id, question_id{', answer_files' if has_files else ''} FROM attempt_answers WHERE attempt_id = %s",
        [attempt_id],
    )
    cleared = 0
    for row in rows:
        if str(row['question_id']) in locked:
            continue
        sets, params = ['answer = %s'], [json.dumps({'value': ''})]
        if has_files:
            for item in _sx_answer_files(row.get('answer_files')):
                if item.get('path'):
                    delete_private(item['path'])
            sets.append('answer_files = %s')
            params.append('[]')
        if has_mark:
            sets.append('marked_for_review = false')
        erd_execute(f"UPDATE attempt_answers SET {', '.join(sets)} WHERE id = %s", [*params, row['id']])
        cleared += 1
    return cleared


def _sx_lock_answers(attempt_id, question_ids) -> None:
    """«امکان تغییر پاسخ» off: answered questions among question_ids keep their answer from now on."""
    question_ids = [str(item) for item in question_ids if item]
    if not question_ids or not erd_has_column('attempt_answers', 'locked_at'):
        return
    files = ', answer_files' if erd_has_column('attempt_answers', 'answer_files') else ''
    rows = erd_rows(
        f"""
        SELECT id, answer{files} FROM attempt_answers
        WHERE attempt_id = %s AND locked_at IS NULL AND question_id IN ({', '.join(['%s'] * len(question_ids))})
        """,
        [attempt_id, *question_ids],
    )
    answered = [row['id'] for row in rows if _sx_result_values(row.get('answer')) or _sx_answer_files(row.get('answer_files'))]
    for answer_id in answered:
        erd_execute('UPDATE attempt_answers SET locked_at = %s WHERE id = %s', [timezone.now(), answer_id])


ANSWER_TEXT_MAX = 50000  # characters per posted answer value; a long essay fits, a flood does not


def _sx_save_attempt_answers(request, attempt_id):
    """Save posted answers of an attempt the caller already verified belongs to this student.

    Answers are accepted only while the attempt accepts answers (in progress, not submitted, within time),
    and only for questions of the attempt's exam; anything else in the POST is ignored. A question whose
    tutorial feedback was shown keeps its answer; only its «علامت‌گذاری» still changes. The page also posts
    ``seen_<id>`` for the question on screen, so its mark is saved even while it has no answer.
    """
    if not _sx_attempt_accepts_answers(attempt_id):
        return 0
    attempt = erd_row('SELECT exam_id FROM exam_attempts WHERE id = %s', [attempt_id]) or {}
    rules = _sx_exam_rules(attempt['exam_id']) if attempt else dict(EXAM_RULE_DEFAULTS)
    locked = _sx_locked_question_ids(attempt_id)
    allowed_questions = {
        str(row['question_id']): row
        for row in erd_rows(
            """
            SELECT eq.question_id, q.type, q.ordering_items, q.matching_pairs, q.scoring_settings
            FROM exam_questions eq
            JOIN exam_attempts ea ON ea.exam_id = eq.exam_id
            JOIN questions q ON q.id = eq.question_id
            WHERE ea.id = %s
            """,
            [attempt_id],
        )
    }
    saved = 0
    posted_questions = dict.fromkeys(
        key.split('_', 1)[1] for key in request.POST.keys() if key.startswith(('answer_', 'seen_'))
    )
    for question_id in posted_questions:
        if question_id not in allowed_questions:
            continue
        key = f'answer_{question_id}'
        values = [value[:ANSWER_TEXT_MAX] for value in request.POST.getlist(key)]
        answer_value = values if len(values) > 1 else (values[0] if values else '')
        question = allowed_questions[question_id]
        if question.get('type') in ('ordering', 'matching') and key in request.POST:
            answer_value = _sx_decode_item_answer(question['type'], question, attempt_id, values[0] if values else '')
        stored = {'value': answer_value}
        if question.get('type') == 'short_answer' and isinstance(answer_value, str):
            limit = int(_sx_float((_sx_json(question.get('scoring_settings'), {}) or {}).get('max_chars'), 0))
            if limit:
                stored['value'] = answer_value[:limit]
        if question.get('type') in MANUAL_ANSWER_KINDS and request.POST.get(f'answer_delta_{question_id}'):
            delta = clean_delta(request.POST.get(f'answer_delta_{question_id}'))
            if delta.get('ops'):
                stored['delta'] = delta
                stored['value'] = delta_text(delta).strip()[:ANSWER_TEXT_MAX]
        answer = json.dumps(stored, ensure_ascii=False)
        # «امکان علامت‌گذاری سوال» off: the review mark is not offered, and none is stored.
        marked = bool(request.POST.get(f'mark_{question_id}')) and rules['allow_flagging_questions']
        existing = erd_row(
            'SELECT id FROM attempt_answers WHERE attempt_id = %s AND question_id = %s LIMIT 1',
            [attempt_id, question_id],
        )
        if question_id in locked or key not in request.POST:
            # The answer stays as it is: locked by tutorial feedback, or nothing chosen yet (only the mark changed).
            if not erd_has_column('attempt_answers', 'marked_for_review'):
                continue
            if existing:
                erd_execute('UPDATE attempt_answers SET marked_for_review = %s WHERE id = %s', [marked, existing['id']])
            elif marked and question_id not in locked:
                erd_execute(
                    'INSERT INTO attempt_answers (id, attempt_id, question_id, answer, needs_manual_grading, marked_for_review) '
                    'VALUES (%s, %s, %s, %s, false, true)',
                    [str(uuid.uuid4()), attempt_id, question_id, json.dumps({'value': ''})],
                )
            continue
        if existing:
            if erd_has_column('attempt_answers', 'marked_for_review'):
                erd_execute('UPDATE attempt_answers SET answer = %s, marked_for_review = %s WHERE id = %s', [answer, marked, existing['id']])
            else:
                erd_execute('UPDATE attempt_answers SET answer = %s WHERE id = %s', [answer, existing['id']])
        else:
            columns = 'id, attempt_id, question_id, answer, needs_manual_grading'
            placeholders = '%s, %s, %s, %s, false'
            params = [str(uuid.uuid4()), attempt_id, question_id, answer]
            if erd_has_column('attempt_answers', 'marked_for_review'):
                columns += ', marked_for_review'
                placeholders += ', %s'
                params.append(marked)
            erd_execute(f'INSERT INTO attempt_answers ({columns}) VALUES ({placeholders})', params)
        saved += 1
    if not rules['allow_answer_changes']:
        # The page posts lock_<id> when the student leaves an answered question (moving on, or leaving its field).
        _sx_lock_answers(attempt_id, [key[len('lock_'):] for key in request.POST if key.startswith('lock_')
                                      and key[len('lock_'):] in allowed_questions])
    return saved


# Essay answer uploads: kind -> (extensions, max bytes). Files go to PRIVATE_MEDIA_ROOT, never to a public URL.
ANSWER_FILE_RULES = {
    'image': ({'jpg', 'jpeg', 'png', 'webp'}, 10 * 1024 * 1024),
    'audio': ({'webm', 'ogg', 'mp3', 'wav', 'm4a'}, 20 * 1024 * 1024),
    'video': ({'mp4', 'webm', 'mov'}, 100 * 1024 * 1024),  # mov: iPhone camera
    'file': ({'pdf', 'docx'}, 20 * 1024 * 1024),
}
ANSWER_FILES_MAX = 5


def _sx_answer_files(value):
    files = _sx_json(value, []) or []
    return [item for item in files if isinstance(item, dict) and item.get('id') and item.get('path')]


def _sx_save_answer_files(request, attempt_id, rows):
    """Store/remove essay answer files for this attempt. Returns user-facing errors.

    Only questions of this attempt are touched, only in the formats the teacher allowed, and never after
    submission. Autosave requests (XHR) never carry files.
    """
    if request.headers.get('X-Requested-With') == 'XMLHttpRequest' or not erd_has_column('attempt_answers', 'answer_files'):
        return []
    if not rows or not _sx_attempt_accepts_answers(attempt_id):
        return []
    errors = []
    locked = _sx_locked_question_ids(attempt_id)
    for row in rows:
        if (row.get('type') or '') not in {'essay', 'descriptive', 'media_response'}:
            continue
        question_id = str(row['question_id'])
        if question_id in locked:
            continue
        formats = _essay_view(_sx_json(row.get('scoring_settings'), {}) or {})['answer_formats']
        uploads = [(kind, uploaded) for kind in ANSWER_FILE_RULES if kind in formats
                   for uploaded in request.FILES.getlist(f'upload_{question_id}_{kind}')]
        removals = set(request.POST.getlist(f'remove_file_{question_id}'))
        # «ضبط دوباره»: a new recording of this kind replaces the earlier one(s), once it is stored successfully.
        replace_kinds = {kind for kind in request.POST.getlist(f'replace_file_{question_id}') if kind in ('audio', 'video')}
        if not uploads and not removals:
            continue
        files = _sx_answer_files(row.get('answer_files'))
        for item in files:
            if item['id'] in removals:
                delete_private(item['path'])
        files = [item for item in files if item['id'] not in removals]
        replaced = [item for item in files if item['kind'] in replace_kinds and any(kind == item['kind'] for kind, _uploaded in uploads)]
        added_kinds = set()
        for kind, uploaded in uploads:
            extensions, limit = ANSWER_FILE_RULES[kind]
            extension = file_extension(uploaded.name)
            if len(files) - len(replaced) >= ANSWER_FILES_MAX:
                errors.append(f'حداکثر {ANSWER_FILES_MAX} فایل برای هر پاسخ مجاز است.')
                break
            if extension not in extensions:
                errors.append(f'نوع فایل «{uploaded.name}» برای این بخش مجاز نیست.')
            elif uploaded.size > limit:
                errors.append(f'حجم فایل «{uploaded.name}» بیش از {limit // (1024 * 1024)} مگابایت است.')
            elif not signature_ok(uploaded, extension):
                errors.append(f'محتوای فایل «{uploaded.name}» با پسوند آن هم‌خوانی ندارد.')
            else:
                files.append({
                    'id': uuid.uuid4().hex, 'name': uploaded.name[:150], 'kind': kind, 'ext': extension, 'size': uploaded.size,
                    'path': store_private(uploaded, f'answer-files/{attempt_id}', extension),
                })
                added_kinds.add(kind)
        for item in [item for item in replaced if item['kind'] in added_kinds]:
            delete_private(item['path'])
            files.remove(item)
        payload = json.dumps(files, ensure_ascii=False)
        if erd_row('SELECT id FROM attempt_answers WHERE attempt_id = %s AND question_id = %s', [attempt_id, question_id]):
            erd_execute('UPDATE attempt_answers SET answer_files = %s WHERE attempt_id = %s AND question_id = %s',
                        [payload, attempt_id, question_id])
        else:
            erd_execute(
                'INSERT INTO attempt_answers (id, attempt_id, question_id, answer, needs_manual_grading, answer_files) '
                'VALUES (%s, %s, %s, %s, false, %s)',
                [str(uuid.uuid4()), attempt_id, question_id, json.dumps({'value': ''}), payload],
            )
    return errors


