@erd_role_required('student')
def student_settings(request):
    from . import student_settings as page

    student_id = request.erd_profile_id
    tab = request.POST.get('settings_tab') if request.method == 'POST' else request.GET.get('tab')
    tab = tab if tab in page.SETTINGS_TABS else 'personal'
    errors = []
    if request.method == 'POST' and tab == 'personal':
        errors = page.save_personal_info(request, student_id)
        if not errors:
            return redirect(f'{reverse("core:student_settings")}?tab=personal&saved=1')
    elif request.method == 'POST' and tab == 'workspace':
        page.save_workspace(request, student_id)
        save_posted_appearance(student_id, request.POST)  # «تنظیمات ظاهری» card
        return redirect(f'{reverse("core:student_settings")}?tab=workspace&saved=1')
    elif request.method == 'POST' and tab == 'security':
        action = request.POST.get('security_action', '').partition(':')[0]
        errors = page.handle_security_action(request, student_id) if action else page.save_privacy(request, student_id)
        if not errors:
            return redirect(f'{reverse("core:student_settings")}?tab=security&' + (f'done={action}' if action else 'saved=1'))
    context = {'student': _sx_student_context(request), 'tab': tab, 'errors': errors}
    if tab == 'security':
        context.update(_teacher_security_context(request, student_id))
        context['show_avatar_to_teacher'] = page.show_avatar_to_teacher(student_id)
        context['security_failed_action'] = request.POST.get('security_action', '').partition(':')[0] if errors else ''
        context['security_done'] = request.GET.get('done', '')
    if tab == 'workspace':
        context['notification_rows'] = page.notification_rows(page.preferences(student_id))
        context['workspace_fixed'] = page.WORKSPACE_FIXED
    if tab == 'personal':
        personal = page.personal_info(student_id)
        if errors:  # show what the student typed, not the stored values
            personal.update({name: request.POST.get(name, '') for name in ('first_name', 'last_name')})
            if 'phone' in request.POST:
                personal['phone'], personal['phone_editing'] = request.POST['phone'], True
        context['personal'] = personal
        context['personal_readonly'] = page.readonly_fields(personal)
    return render(request, 'student/settings/page.html', context)


EXAM_CODE_PREFIX = 'MQ-'
EXAM_JOIN_LOGIN_KEY = 'exam_join_login_for'  # the code a guest was sent to sign in for
EXAM_CODE_LENGTH = 6
# The same keys on the Persian layout: پ=M ض=Q ش=A ذ=B ز=C ی/ي=D ث=E ب=F.
_EXAM_CODE_FA_KEYS = str.maketrans({'پ': 'M', 'ض': 'Q', 'ش': 'A', 'ذ': 'B', 'ز': 'C', 'ی': 'D', 'ي': 'D', 'ث': 'E', 'ب': 'F'})


def exam_access_code(exam_id) -> str:
    """«کد آزمون»: what the teacher gives students to join from the home page (MQ- and the id's first six hex digits)."""
    return f"{EXAM_CODE_PREFIX}{str(exam_id or '').replace('-', '')[:EXAM_CODE_LENGTH].upper()}"


def _normalize_exam_code(value) -> str:
    """The six hex digits of a typed code («mq-1a2b3c», «۱A2B3C», «MQ 1A2B3C»), or '' when it is not one."""
    text = str(value or '').translate(_EXAM_CODE_FA_KEYS)  # typed with the Persian keyboard layout
    text = _normalize_answer_text(text, persian=True).upper()
    text = re.sub(r'[\s\-_‌]+', '', text)
    if text.startswith(EXAM_CODE_PREFIX.rstrip('-')):
        text = text[len(EXAM_CODE_PREFIX) - 1:]
    return text.lower() if re.fullmatch(r'[0-9A-F]{%d}' % EXAM_CODE_LENGTH, text) else ''


RECEIPT_ALPHABET = '23456789ABCDEFGHJKLMNPQRSTUVWXYZ'  # matches migration 0058: no 0/O or 1/I to mix up
RECEIPT_RANDOM_LENGTH = 6


def attempt_receipt_code(attempt_id) -> str:
    """«شناسه رسید» of a submitted attempt: «کد آزمون» and six random characters (MQ-1A2B3C-7KQ4RZ).

    Given once, on submission, and kept; the unique index (migration 0058) makes it one attempt's only.
    An attempt not submitted has none."""
    if not erd_has_column('exam_attempts', 'receipt_code'):
        return ''
    row = erd_row('SELECT exam_id, receipt_code, submitted_at FROM exam_attempts WHERE id = %s', [attempt_id])
    if not row or row.get('receipt_code') or not row.get('submitted_at'):
        return (row or {}).get('receipt_code') or ''
    for _ in range(10):
        code = f"{exam_access_code(row['exam_id'])}-{''.join(secrets.choice(RECEIPT_ALPHABET) for _ in range(RECEIPT_RANDOM_LENGTH))}"
        try:
            with transaction.atomic():
                erd_execute('UPDATE exam_attempts SET receipt_code = %s WHERE id = %s AND receipt_code IS NULL', [code, attempt_id])
            break
        except IntegrityError:  # taken by another attempt: draw again
            continue
    return (erd_row('SELECT receipt_code FROM exam_attempts WHERE id = %s', [attempt_id]) or {}).get('receipt_code') or ''


def normalize_receipt_code(value) -> str:
    """A typed receipt id («mq-1a2b3c-7kq4rz», Persian digits, spaces) as stored, or '' when it is not one."""
    text = re.sub(r'[\s\-_‌]+', '', _normalize_answer_text(str(value or ''), persian=True).upper())
    if text.startswith('MQ'):
        text = text[2:]
    pattern = r'([0-9A-F]{%d})([%s]{%d})' % (EXAM_CODE_LENGTH, RECEIPT_ALPHABET, RECEIPT_RANDOM_LENGTH)
    match = re.fullmatch(pattern, text)
    return f'{EXAM_CODE_PREFIX}{match.group(1)}-{match.group(2)}' if match else ''


def _exam_ids_for_code(code) -> list:
    """Every exam whose «کد آزمون» this is (two exams may share the six digits; callers keep the one the user may reach)."""
    return [str(row['id']) for row in erd_rows(
        "SELECT id FROM exams WHERE LOWER(REPLACE(CAST(id AS TEXT), '-', '')) LIKE %s", [f'{code}%'])]


def _exam_for_code(code, student_id):
    """The exam with this code that the student may take (published, not cancelled, in its audience), else None."""
    for exam_id in _exam_ids_for_code(code):
        if erd_row('SELECT 1 AS ok FROM exams WHERE id = %s AND COALESCE(is_cancelled, false) = false', [exam_id]):
            exam = _sx_exam_row(exam_id, student_id)
            if exam:
                return exam
    return None


def _exam_code_staff_page(request, role, code):
    """Where a teacher, academic manager or admin lands with an exam code: that exam in their own panel, or None
    when no exam with this code is theirs (a teacher's own or one they are staff on; a manager's units; any for admin)."""
    for exam_id in _exam_ids_for_code(code):
        if role == 'teacher':
            if not _teacher_owned_exam(request.erd_profile_id, exam_id, staff=True):
                continue
            exam = erd_row('SELECT id, lifecycle_status, is_published, is_cancelled, start_at, end_at FROM exams WHERE id = %s', [exam_id])
            if erd_row('SELECT 1 AS ok FROM exams WHERE id = %s AND teacher_id = %s', [exam_id, request.erd_profile_id])                     and _teacher_exam_editable(exam):
                return reverse('core:teacher_exam_edit', args=[exam_id])
            now = timezone.now()
            start, end = erd_datetime(exam.get('start_at')), erd_datetime(exam.get('end_at'))
            running = bool(exam.get('is_published')) and start and start <= now and (not end or now <= end)
            return f"{reverse('core:teacher_monitoring' if running else 'core:teacher_results')}?{urlencode({'exam': exam_id})}"
        if role in ('academic_manager', 'admin') and _erd_exam_in_manager_scope(request, exam_id):
            from .exam_hub import hub_url
            return hub_url('manager', exam_id)
    return None


def exam_join(request):
    """«ورود با کد آزمون» on the home page: sign in if needed, then straight to that exam: a student to its entry
    page, a teacher / academic manager / admin to the exam in their own panel (_exam_code_staff_page).

    The entry page then handles every moment of the exam: not open yet (countdown), rules and identity,
    resuming an attempt, entry time over, or the receipt when no attempt is left."""
    raw = (request.POST.get('code') or request.GET.get('code') or '').strip()[:40]
    code = _normalize_exam_code(raw)

    def back(reason):  # the error is shown in the home page's code box, which the page scrolls to
        return redirect(f"{reverse('core:home')}?{urlencode({'join': reason, 'code': raw[:20]})}#join")

    if not code:
        return back('invalid' if raw else 'missing')
    display = f'{EXAM_CODE_PREFIX}{code.upper()}'
    if not request.user.is_authenticated:
        # A code no exam has is refused here, before asking anyone to sign in.
        if not any(erd_row('SELECT 1 AS ok FROM exams WHERE id = %s AND COALESCE(is_cancelled, false) = false', [exam_id])
                   for exam_id in _exam_ids_for_code(code)):
            return back('no_exam')
        request.session[EXAM_JOIN_LOGIN_KEY] = display  # this sign-in is only for the code (undone below if it fails)
        query = urlencode({'next': f"{reverse('core:exam_join')}?{urlencode({'code': display})}", 'code': display})
        return redirect(f"{reverse('core:login')}?{query}")
    signed_in_for_code = request.session.pop(EXAM_JOIN_LOGIN_KEY, None) == display

    def refuse(reason):
        """The code does not lead this account anywhere: a sign-in made just for it is undone, so the next try
        asks for an account again."""
        if signed_in_for_code:
            logout(request)
        return back(reason)

    role = erd_primary_role(request.user)
    profile = erd_profile_for_user(request.user)
    if not profile or role not in ('student', 'teacher', 'academic_manager', 'admin'):
        return refuse('role')
    if role != 'student':  # staff open the exam in their own panel; the panel pages check access again
        request.erd_profile, request.erd_profile_id, request.erd_role = profile, profile['id'], role
        page = _exam_code_staff_page(request, role, code)
        return redirect(page) if page else refuse('not_found_staff')
    exam = _exam_for_code(code, profile['id'])
    if not exam:
        return refuse('not_found')
    if practice_redirect := _sx_practice_exam_redirect(exam):
        return practice_redirect
    attempt = _sx_attempt_for_exam(exam['id'], profile['id'])
    if attempt and attempt.get('status') == 'in_progress' and attempt.get('started_at') and not attempt.get('submitted_at'):
        return redirect('core:student_attempt', attempt_id=attempt['id'])
    return redirect('core:student_exam_entry', exam_id=exam['id'])


def _sx_practice_exam_redirect(exam):
    """Practice exams run through their own section (several attempts, a chosen mode), never the course-exam flow."""
    if exam.get('exam_mode') == PRACTICE_EXAM_MODE:
        return redirect('core:student_practice_detail', exam_id=exam['id'])
    return None


def _sx_attempt_count(exam_id, student_id) -> int:
    """Attempts of a course exam that are used up: submitted, or closed because their time ran out."""
    return erd_count('exam_attempts', "exam_id = %s AND student_id = %s AND (submitted_at IS NOT NULL OR status = 'expired')",
                     [exam_id, student_id])


def _sx_attempts_left(exam, student_id) -> bool:
    """«تعداد تلاش مجاز» (0: unlimited) leaves room for a new attempt."""
    limit = exam['rules']['max_attempts']
    return limit == 0 or _sx_attempt_count(exam['id'], student_id) < max(limit, 1)


def _sx_entry_key(exam_id) -> str:
    return f'exam_entry_ok_{exam_id}'


def _sx_identity_matches(request, code) -> bool:
    """«احراز هویت داوطلب»: the code is the student's own national id or student number (Persian digits allowed)."""
    code = _normalize_answer_text(code or '', persian=True).replace(' ', '')
    if not code:
        return False
    row = erd_row(
        """
        SELECT p.national_id, sp.student_number, p.identifier
        FROM profiles p LEFT JOIN student_profiles sp ON sp.user_id = p.id WHERE p.id = %s
        """,
        [request.erd_profile_id],
    ) or {}
    known = {_normalize_answer_text(str(value), persian=True).replace(' ', '') for value in row.values() if value}
    return code in known


def _sx_entry_context(request, exam, attempt):
    """What the detail and entry pages show about entering: the window, rules, attempts and the IP rule."""
    now = timezone.now()
    access_starts_at = exam.get('access_starts_at')
    resuming = bool(attempt and attempt.get('status') == 'in_progress' and not attempt.get('submitted_at'))
    used_up = bool(attempt) and not resuming and not _sx_attempts_left(exam, request.erd_profile_id)
    return {
        'can_enter': (exam['starts_at'] <= now <= exam['entry_ends_at'] or resuming) and not used_up,
        'entry_expired': now > exam['entry_ends_at'] and not resuming,
        'access_not_open': bool(access_starts_at and now < access_starts_at),
        'access_starts_at': access_starts_at,
        'seconds_until_start': max(0, int((exam['starts_at'] - now).total_seconds())),
        'question_count': exam['question_count'],
        'rule_lines': _sx_exam_rule_lines(exam),
        'attempts_used': _sx_attempt_count(exam['id'], request.erd_profile_id),
        'attempts_limit': exam['rules']['max_attempts'],
        'attempts_used_up': used_up,
        'ip_blocked': not _sx_ip_allowed(request, exam['rules']),
    }


@never_cache
@erd_role_required('student')
def student_exam_detail(request, exam_id):
    exam = _sx_exam_row(exam_id, request.erd_profile_id)
    if not exam:
        raise Http404('آزمون پیدا نشد.')
    if practice_redirect := _sx_practice_exam_redirect(exam):
        return practice_redirect
    attempt = _sx_attempt_for_exam(exam_id, request.erd_profile_id)
    return render(request, 'student/exam_detail.html', {
        'student': _sx_student_context(request),
        'exam': exam,
        'attempt': attempt,
        **_sx_entry_context(request, exam, attempt),
    })


@never_cache
@erd_role_required('student')
def student_exam_entry(request, exam_id):
    exam = _sx_exam_row(exam_id, request.erd_profile_id)
    if not exam:
        raise Http404('آزمون پیدا نشد.')
    if practice_redirect := _sx_practice_exam_redirect(exam):
        return practice_redirect
    attempt = _sx_attempt_for_exam(exam_id, request.erd_profile_id)
    entry = _sx_entry_context(request, exam, attempt)
    if attempt and attempt.get('submitted_at') and entry['attempts_used_up']:
        return redirect('core:student_attempt_receipt', attempt_id=attempt['id'])
    rules = exam['rules']
    entry_error = ''
    if request.method == 'POST':
        if entry['access_not_open']:
            entry_error = 'ورود به این آزمون هنوز باز نشده است.'
        elif entry['ip_blocked']:
            entry_error = 'شرکت در این آزمون از شبکه‌ی فعلی شما مجاز نیست.'
        elif not request.POST.get('accept_rules'):
            entry_error = 'برای ادامه باید قوانین آزمون را بپذیرید.'
        elif rules['settings_enforced'] and rules['identity_verification_required'] and not _sx_identity_matches(request, request.POST.get('identity_code')):
            entry_error = 'کد ملی یا شماره دانشجویی واردشده با اطلاعات شما مطابقت ندارد.'
        else:
            request.session[_sx_entry_key(exam_id)] = True
            return redirect(f"{reverse('core:student_exam_entry', args=[exam_id])}?ready=1")
    return render(request, 'student/exam_entry.html', {
        'student': _sx_student_context(request),
        'exam': exam,
        # The entry step passed in this session (not just ?ready=1 in the address), or an attempt to resume.
        'can_start': bool(request.session.get(_sx_entry_key(exam_id)) or (attempt and attempt.get('status') == 'in_progress')),
        'entry_error': entry_error,
        'identity_code': request.POST.get('identity_code', ''),
        'needs_identity': rules['settings_enforced'] and rules['identity_verification_required'],
        **entry,
    })


@erd_role_required('student')
def student_exam_start(request, exam_id):
    exam = _sx_exam_row(exam_id, request.erd_profile_id)
    if not exam:
        raise Http404('آزمون پیدا نشد.')
    if practice_redirect := _sx_practice_exam_redirect(exam):
        return practice_redirect
    if request.method != 'POST':  # an attempt is created only by the entry page's button
        return redirect('core:student_exam_detail', exam_id=exam_id)
    attempt = _sx_attempt_for_exam(exam_id, request.erd_profile_id)
    # A started attempt may be resumed (its own time limit applies); a new start must fall inside the exam window.
    resuming = bool(attempt and attempt.get('started_at') and attempt.get('status') == 'in_progress' and not attempt.get('submitted_at'))
    if not resuming and attempt and not _sx_attempts_left(exam, request.erd_profile_id):
        if attempt.get('submitted_at'):
            return redirect('core:student_attempt_receipt', attempt_id=attempt['id'])
        messages.error(request, 'فرصت شرکت شما در این آزمون تمام شده است.')
        return redirect('core:student_exam_detail', exam_id=exam_id)
    if not _sx_ip_allowed(request, exam['rules']):
        messages.error(request, 'شرکت در این آزمون از شبکه‌ی فعلی شما مجاز نیست.')
        return redirect('core:student_exam_detail', exam_id=exam_id)
    now = timezone.now()
    if not resuming and not exam['starts_at'] <= now <= exam['entry_ends_at']:
        messages.error(request, 'آزمون هنوز شروع نشده است.' if now < exam['starts_at'] else 'زمان ورود به این آزمون به پایان رسیده است.')
        return redirect('core:student_exam_detail', exam_id=exam_id)
    if not resuming and exam['needs_entry'] and not request.session.get(_sx_entry_key(exam_id)):
        messages.error(request, 'ابتدا قوانین آزمون را بپذیرید' + (' و هویت خود را تأیید کنید.' if exam['rules']['identity_verification_required'] else '.'))
        return redirect('core:student_exam_entry', exam_id=exam_id)
    if not resuming:
        with transaction.atomic():
            # Two quick starts must not both insert: lock the student's profile row and look again (as practice starts do).
            if connection.vendor == 'postgresql':
                erd_row('SELECT id FROM profiles WHERE id = %s FOR UPDATE', [request.erd_profile_id])
            latest = _sx_attempt_for_exam(exam_id, request.erd_profile_id)
            if latest and latest.get('status') == 'in_progress' and not latest.get('submitted_at'):
                attempt = latest
            elif not latest or _sx_attempts_left(exam, request.erd_profile_id):
                attempt_id = str(uuid.uuid4())
                erd_execute(
                    """
                    INSERT INTO exam_attempts (id, exam_id, student_id, started_at, status, is_graded)
                    VALUES (%s, %s, %s, %s, %s, false)
                    """,
                    [attempt_id, exam_id, request.erd_profile_id, timezone.now(), 'in_progress'],
                )
                attempt = {'id': attempt_id}
            else:
                return redirect('core:student_attempt_receipt', attempt_id=latest['id'])
        request.session.pop(_sx_entry_key(exam_id), None)  # each attempt passes the entry step again
    erd_execute(
        "UPDATE exam_attempts SET status = %s, started_at = COALESCE(started_at, %s) WHERE id = %s",
        ['in_progress', timezone.now(), attempt['id']],
    )
    return redirect('core:student_attempt', attempt_id=attempt['id'])


def _sx_attempt_items(rows, attempt_id, locked_ids):
    """The exam page's question items built from _sx_attempt_rows-shaped rows (also used by exam_preview).

    attempt_id seeds the per-attempt option/item order and the ordering/matching tokens; never carries correct answers."""
    items = []
    for index, row in enumerate(rows, start=1):
        kind = row.get('type') or 'single'
        settings_data = _sx_json(row.get('scoring_settings'), {}) or {}
        settings_data = settings_data if isinstance(settings_data, dict) else {}
        if kind in ('multi', 'fill_blank', 'numeric', 'image_label'):
            raw = _sx_json(row.get('answer'), {})
            answer = raw.get('value') if isinstance(raw, dict) else raw
            if kind == 'fill_blank' and isinstance(answer, str):
                answer = answer.split('|')
            if not isinstance(answer, list):
                answer = [answer] if answer else []
        else:
            answer = _sx_answer_value(row.get('answer'))
        item = {
            'index': index,
            'question_id': row['question_id'],
            'text': str(row.get('text') or '').strip(),
            'type': kind,
            'type_label': _sx_type_label(kind),
            'options': _sx_question_options(row.get('options'), kind),
            'media': _sx_question_media(row.get('question_media')),
            'answer': answer,
            'answered': any(str(value).strip() for value in answer) if isinstance(answer, list) else bool(answer),
            'marked': bool(row.get('marked')),
            'points': _sx_float(row.get('question_points'), 0),
            'suggested_seconds': int(_sx_float(row.get('suggested_time_seconds'), 0)),
        }
        if kind in ('single', 'multi') and row.get('exam_shuffle_options'):  # an exam setting, not a question one
            # Stable per attempt so the order does not change between page loads.
            random.Random(f"{attempt_id}-{row['question_id']}").shuffle(item['options'])
        if kind == 'multi':
            item['max_select'] = int(_sx_float(settings_data.get('max_correct'), 0))
            item['min_select'] = int(_sx_float(settings_data.get('min_correct'), 1))
        if kind == 'ordering':
            item['ordering_items'] = _sx_ordering_display_items(row.get('ordering_items'), row['question_id'], attempt_id)
            item['answer'] = _sx_encode_item_answer(kind, row, attempt_id, answer)
        elif kind == 'matching':
            item['matching_left'], item['matching_right'] = _sx_matching_display_columns(row.get('matching_pairs'), row['question_id'], settings_data, attempt_id)
            item['answer'] = _sx_encode_item_answer(kind, row, attempt_id, answer)
            item['matching_many_to_one'] = settings_data.get('matching_mode') == 'many_to_one'
        elif kind == 'fill_blank':
            item['blank_segments'] = _sx_fill_blank_segments(item['text'])
            for segment in item['blank_segments']:
                if segment['kind'] == 'blank':
                    segment['value'] = answer[segment['index'] - 1] if segment['index'] <= len(answer) else ''
            # Rich stem with inputs in place of the markers; '' means render blank_segments instead.
            item['blank_html'] = _fill_blank_stem_html(settings_data, item['text'], row['question_id'], answer)
            item['blank_hints'] = [
                {'index': number, 'media': blank['media'], 'media_kind': _media_kind(blank['media'])}
                for number, blank in enumerate((_sx_json(row.get('accepted_answers'), []) or []), start=1)
                if isinstance(blank, dict) and blank.get('media')
            ]
        if kind != 'fill_blank':
            item['text_html'] = _question_stem_html(settings_data)
        if kind in question_kinds.V2_TYPES:
            item.update(question_kinds.student_view(kind, row, settings_data, answer, attempt_id))
        if kind == 'short_answer':
            item['max_chars'] = int(_sx_float(settings_data.get('max_chars'), 0))
        if item['type'] in {'essay', 'descriptive', 'media_response'}:
            raw_answer = _sx_json(row.get('answer'), {})
            item['answer_delta'] = raw_answer.get('delta') if isinstance(raw_answer, dict) and isinstance(raw_answer.get('delta'), dict) else None
            essay_view = _essay_view(settings_data)
            item['student_instructions'] = essay_view['student_instructions']
            item['answer_formats'] = essay_view['answer_formats']
            item['answer_files'] = [
                {**file, 'url': reverse('core:attempt_answer_file', args=[attempt_id, file['id']])}
                for file in _sx_answer_files(row.get('answer_files'))
            ]
            item['answered'] = item['answered'] or bool(item['answer_files'])
            item['recorded_kinds'] = {file['kind'] for file in item['answer_files'] if file.get('kind') in ('audio', 'video')}
            item['upload_rules'] = {
                kind: {'accept': ','.join(f'.{ext}' for ext in sorted(rule[0])), 'mb': rule[1] // (1024 * 1024)}
                for kind, rule in ANSWER_FILE_RULES.items() if kind in item['answer_formats']
            }
        item['locked'] = str(row['question_id']) in locked_ids  # «امکان تغییر پاسخ» off and already left
        items.append(item)
    return items


def _sx_render_attempt_page(request, context):
    """The exam page (student/attempt.html) — also exam_preview's — or, for ``GET ?part=questions``, every question of
    the attempt with its stored answer in one small response (student/_attempt_questions.html), which the page loads
    once in the background so moving between questions never waits for the network («Moving between questions» in
    attempt.html). Served only where the student may open any question and change any answer anyway (one question
    per page, going back allowed, answers may change, no tutorial feedback); otherwise 404, so a forward-only or
    locking exam never shows a question early."""
    if request.GET.get('part') == 'questions':
        rules = context['page_rules']
        if (request.method != 'GET' or not rules['one_per_page'] or not rules['back'] or rules['lock_on_leave']
                or (context.get('practice') or {}).get('tutorial')):
            raise Http404('این بخش برای این آزمون در دسترس نیست.')
        return render(request, 'student/_attempt_questions.html', context)
    return render(request, 'student/attempt.html', context)


@never_cache
@erd_role_required('student')
def student_attempt(request, attempt_id):
    rows = _sx_attempt_rows(attempt_id, request.erd_profile_id)
    if not rows:
        raise Http404('تلاش آزمون پیدا نشد.')
    current_index = min(max(1, _em_int(request.GET.get('q'), 1)), len(rows))
    is_xhr = request.headers.get('X-Requested-With') == 'XMLHttpRequest'
    finished = rows[0].get('submitted_at') or (rows[0].get('status') or 'in_progress') not in ('in_progress', '')
    if finished and request.method == 'GET' and not is_xhr:
        return redirect('core:student_attempt_receipt', attempt_id=attempt_id)
    rules = _sx_attempt_page_rules(attempt_id, request.erd_profile_id, rows[0]['exam_id'])
    if not rows[0].get('submitted_at') and not _sx_ip_allowed(request, rules):
        if is_xhr:
            return JsonResponse({'ok': False, 'error': 'شرکت در این آزمون از این شبکه مجاز نیست.'}, status=403)
        return render(request, 'student/attempt_device.html', {
            'exam_title': rows[0].get('exam_title') or 'آزمون', 'ip_blocked': True}, status=403)
    if not rows[0].get('submitted_at'):
        if request.method == 'POST' and request.POST.get('action') == 'take_over':
            _sx_take_over_attempt(request, attempt_id)
            return redirect('core:student_attempt', attempt_id=attempt_id)
        if _sx_attempt_device(request, attempt_id) == 'other':
            if is_xhr:  # the page reloads on 423 and shows the take-over screen
                return JsonResponse({'ok': False, 'error': 'این آزمون روی دستگاه دیگری باز است.'}, status=423)
            if request.method == 'POST':
                messages.error(request, 'این آزمون روی دستگاه دیگری باز است؛ پاسخ ذخیره نشد.')
                return redirect('core:student_attempt', attempt_id=attempt_id)
            return render(request, 'student/attempt_device.html', {'exam_title': rows[0].get('exam_title') or 'آزمون'})
    if request.method == 'POST':
        if not _sx_attempt_accepts_answers(attempt_id):
            if is_xhr:
                return JsonResponse({'ok': False, 'error': 'زمان پاسخ‌دهی به پایان رسیده یا آزمون ارسال شده است.'}, status=409)
            messages.error(request, 'زمان پاسخ‌دهی به پایان رسیده یا آزمون ارسال شده است؛ پاسخ جدید ذخیره نشد.')
            return redirect('core:student_attempt_submit', attempt_id=attempt_id)
        if request.POST.get('action') == 'clear_all' and not is_xhr:
            # «پاک کردن همه‌ی پاسخ‌ها»: only where answers may still change; the time keeps running.
            if rules['allow_answer_changes']:
                _sx_clear_attempt_answers(attempt_id)
                messages.success(request, 'همه‌ی پاسخ‌ها و علامت‌ها پاک شد؛ زمان آزمون همچنان ادامه دارد.')
            first_question = 1 if rules['review_answers_enabled'] else min(max(_sx_furthest_question(attempt_id), 1), len(rows))
            return redirect(f"{reverse('core:student_attempt', args=[attempt_id])}?q={first_question}")
        _sx_save_attempt_answers(request, attempt_id)
        for error in _sx_save_answer_files(request, attempt_id, rows):
            messages.error(request, error)
        if is_xhr:
            return JsonResponse({'ok': True})
        action = request.POST.get('action') or ('goto' if request.POST.get('goto') else None)
        if action == 'feedback':
            from . import student_practice as practice

            if practice.attempt_practice_mode(attempt_id, request.erd_profile_id) == 'tutorial':
                error = practice.show_feedback(attempt_id, rows[current_index - 1]['question_id'])
                if error:
                    messages.error(request, error)
        if action == 'finish':
            # «پایان آزمون» submits the answer form, so the answer on screen is saved before the confirmation page.
            if not rules['allow_answer_changes']:
                _sx_lock_answers(attempt_id, [rows[current_index - 1]['question_id']])
            return redirect('core:student_attempt_submit', attempt_id=attempt_id)
        target = current_index
        if action == 'previous':
            target = max(1, current_index - 1)
        elif action == 'next':
            target = min(len(rows), current_index + 1)
        elif action == 'goto':  # a «فهرست سؤالات» cell: saved first, then opened
            target = min(max(1, _em_int(request.POST.get('goto'), current_index)), len(rows))
        if target != current_index and not rules['allow_answer_changes']:
            _sx_lock_answers(attempt_id, [rows[current_index - 1]['question_id']])  # leaving an answered question
        if not rules['review_answers_enabled']:
            # «امکان بازگشت به سوال قبلی» off: only forward, one question at a time.
            furthest = _sx_furthest_question(attempt_id)
            target = furthest + 1 if action == 'next' and current_index >= furthest else furthest
            target = min(max(target, 1), len(rows))
            _sx_set_furthest_question(attempt_id, target)
        return redirect(f"{reverse('core:student_attempt', args=[attempt_id])}?q={target}")
    if not rules['review_answers_enabled'] and not rows[0].get('submitted_at'):
        furthest = min(max(_sx_furthest_question(attempt_id), 1), len(rows))
        if current_index != furthest:
            return redirect(f"{reverse('core:student_attempt', args=[attempt_id])}?q={furthest}")
    if not rules['allow_answer_changes'] and rules['one_question_per_page'] and not rows[0].get('submitted_at'):
        # Answered questions other than the one on screen were left behind (e.g. through the question list).
        _sx_lock_answers(attempt_id, [row['question_id'] for index, row in enumerate(rows, start=1) if index != current_index])
    locked_ids = _sx_locked_question_ids(attempt_id) if not rules['allow_answer_changes'] else set()
    items = _sx_attempt_items(rows, attempt_id, locked_ids)
    current_answer = items[current_index - 1]
    first = rows[0]
    started_at = _sx_dt(first.get('started_at')) or timezone.now()
    cutoff = _sx_exam_cutoff(first.get('exam_end_at'), rules['registration_end_at'])
    remaining_seconds = max(0, int((_sx_attempt_ends_at(started_at, first.get('duration_minutes'), cutoff, first.get('extra_minutes'))
                                    - timezone.now()).total_seconds()))
    answered_count = sum(1 for item in items if item['answered'])
    attempt = {
        'pk': attempt_id,
        'id': attempt_id,
        'exam': {'title': first.get('exam_title') or 'آزمون'},
    }
    practice_context = _sx_practice_attempt_context(attempt_id, request.erd_profile_id, current_answer)
    from . import exam_lock

    if practice_context or first.get('submitted_at') or remaining_seconds <= 0:
        exam_lock.unlock(request, attempt_id)
    else:  # a course exam in progress: other pages of the site bring the student back here (exam_lock.py)
        exam_lock.lock(request, attempt_id)
    return _sx_render_attempt_page(request, {
        'attempt': attempt,
        'current_answer': current_answer,
        'current_index': current_index,
        'total_questions': len(items),
        'answered_count': answered_count,
        'attempt_map': _sx_answer_dashboard(items, current_index),
        'remaining_seconds': remaining_seconds,
        'practice': practice_context,
        # The exam's security settings (step 6 of the wizard); practice attempts are not proctored.
        'proctoring': None if practice_context else {
            'track': bool(first.get('exam_track_tab_exit')), 'fullscreen': bool(first.get('exam_fullscreen_required')),
            'copy_paste': rules['copy_paste_prevention'], 'screenshot': rules['screenshot_prevention'],
            'webcam': rules['webcam_monitoring'], 'mic': rules['mic_monitoring'],
        },
        # The exam's attempt rules (step 2 and «ذخیره خودکار» / «قطع شدن اینترنت» of step 6).
        'items': items,
        'page_rules': {
            'one_per_page': rules['one_question_per_page'],
            'show_list': rules['show_question_list'],
            'flagging': rules['allow_flagging_questions'],
            'back': rules['review_answers_enabled'],
            'lock_on_leave': not rules['allow_answer_changes'],
            'auto_submit': rules['auto_submit_on_time_end'],
            'autosave': rules['autosave_enabled'],
            'autosave_seconds': rules['autosave_interval_seconds'],
            'offline': rules['internet_disconnect_policy'],
        },
    })


def _sx_practice_attempt_context(attempt_id, student_id, current_answer):
    """What the exam page adds for a practice attempt (badge, mode guide, tutorial feedback); None for course exams.

    Once the current question's feedback is shown, each of its options carries ``feedback``: 'correct' for the
    key, 'wrong' for a chosen option outside it, and ``feedback_chosen``."""
    from . import student_practice as practice

    mode = practice.attempt_practice_mode(attempt_id, student_id)
    if not mode:
        return None
    feedback = practice.question_feedback(attempt_id, current_answer['question_id']) if mode == 'tutorial' else None
    if feedback:
        for option in current_answer.get('options') or []:
            state = feedback['option_states'].get(option['value'], {})
            option['feedback'] = 'correct' if state.get('correct') else 'wrong' if state.get('chosen') else ''
            option['feedback_chosen'] = bool(state.get('chosen'))
    return {
        'mode': mode,
        'mode_title': practice.PRACTICE_MODES[mode][0],
        'tutorial': mode == 'tutorial',
        'feedback': feedback,
    }


@never_cache
@erd_role_required('student')
def student_attempt_submit(request, attempt_id):
    rows = _sx_attempt_rows(attempt_id, request.erd_profile_id)
    if not rows:
        raise Http404('تلاش آزمون پیدا نشد.')
    if request.method == 'POST' and not rows[0].get('submitted_at') and _sx_attempt_device(request, attempt_id) == 'other':
        return redirect('core:student_attempt', attempt_id=attempt_id)  # shows the take-over screen; nothing is submitted
    rules = _sx_attempt_page_rules(attempt_id, request.erd_profile_id, rows[0]['exam_id'])
    open_attempt = not rows[0].get('submitted_at') and (rows[0].get('status') or 'in_progress') == 'in_progress'
    if open_attempt and not rules['auto_submit_on_time_end'] and not _sx_attempt_accepts_answers(attempt_id):
        # «ارسال خودکار در پایان زمان» off: an attempt not submitted in time is closed, not submitted.
        erd_execute("UPDATE exam_attempts SET status = 'expired' WHERE id = %s AND submitted_at IS NULL", [attempt_id])
        rows[0]['status'] = 'expired'
    if rows[0].get('status') == 'expired' and not rows[0].get('submitted_at'):
        from . import exam_lock

        exam_lock.unlock(request, attempt_id)
        messages.error(request, 'زمان آزمون به پایان رسید و چون آزمون پیش از آن ارسال نشد، پاسخ‌ها ثبت نشد (ارسال خودکار در این آزمون غیرفعال است).')
        return redirect('core:student_exam_detail', exam_id=rows[0]['exam_id'])
    if request.method == 'POST' and open_attempt and not _sx_ip_allowed(request, rules):
        messages.error(request, 'شرکت در این آزمون از شبکه‌ی فعلی شما مجاز نیست؛ آزمون ارسال نشد.')
        return redirect('core:student_attempt', attempt_id=attempt_id)
    if request.method == 'POST':
        _sx_save_attempt_answers(request, attempt_id)
        if not erd_row('SELECT submitted_at FROM exam_attempts WHERE id = %s AND submitted_at IS NOT NULL', [attempt_id]):
            try:
                result = grade_attempt(attempt_id)
            except Exception:
                # The submission must not be lost: keep it as submitted (ungraded) and leave a trace to regrade it.
                logger.exception('Grading attempt %s failed; saved as submitted without a score.', attempt_id)
                result = {'grading_failed': True}
                erd_execute('UPDATE exam_attempts SET submitted_at = %s, status = %s WHERE id = %s', [timezone.now(), 'submitted', attempt_id])
                attempt_receipt_code(attempt_id)
            log_activity(request.user, 'exam_submitted', 'دانشجو آزمون را ارسال کرد.', request, {'attempt_id': attempt_id, **result})
        from . import exam_lock

        exam_lock.unlock(request, attempt_id)
        return redirect('core:student_attempt_receipt', attempt_id=attempt_id)
    from . import student_practice as practice

    if practice.attempt_practice_mode(attempt_id, request.erd_profile_id):
        return render(request, 'student/practice_review.html', {
            'student': _sx_student_context(request),
            'attempt': {'pk': attempt_id, 'id': attempt_id, 'exam': {'title': rows[0].get('exam_title') or 'آزمون'}},
            **practice.review_context(attempt_id, rows),
        })
    items = []
    for index, row in enumerate(rows, start=1):
        answer = _sx_answer_value(row.get('answer'))
        items.append({'index': index, 'answered': bool(answer), 'marked': bool(row.get('marked'))})
    answered_count = sum(1 for item in items if item['answered'])
    attempt = {'pk': attempt_id, 'id': attempt_id, 'exam': {'title': rows[0].get('exam_title') or 'آزمون'}}
    attempt_map = {
        'items': items,
        'answered_count': answered_count,
        'marked_count': sum(1 for item in items if item['marked']),
    }
    return render(request, 'student/submit_confirm.html', {
        'attempt': attempt,
        'total_questions': len(items),
        'answered_count': answered_count,
        'unanswered_count': max(len(items) - answered_count, 0),
        'marked_count': attempt_map['marked_count'],
        'attempt_map': attempt_map,
    })


@never_cache
@erd_role_required('student')
def student_attempt_receipt(request, attempt_id):
    row = erd_row(
        """
        SELECT ea.id AS pk, ea.id, ea.started_at, ea.submitted_at, ea.score, ea.max_score, e.title AS exam_title
        FROM exam_attempts ea
        JOIN exams e ON e.id = ea.exam_id
        WHERE ea.id = %s AND ea.student_id = %s
        """,
        [attempt_id, request.erd_profile_id],
    )
    if not row:
        raise Http404('رسید آزمون پیدا نشد.')
    from . import student_practice as practice

    if not row.get('submitted_at'):  # attempts are graded on submission; never close one ungraded here
        return redirect('core:student_attempt_submit', attempt_id=attempt_id)
    from . import exam_lock

    exam_lock.unlock(request, attempt_id)
    if practice.attempt_practice_mode(attempt_id, request.erd_profile_id):
        result = next((item for item in _sx_result_rows(request.erd_profile_id, practice=True) if str(item['id']) == str(attempt_id)), None)
        return render(request, 'student/practice_receipt.html', {
            'student': _sx_student_context(request),
            'practice_nav': True,
            'attempt_id': attempt_id,
            'is_pending': not result or result['is_pending'],
            **practice.receipt_context(attempt_id, request.erd_profile_id, _sx_attempt_rows(attempt_id, request.erd_profile_id)),
        })
    attempt = {
        'pk': attempt_id,
        'id': attempt_id,
        'exam': {'title': row.get('exam_title') or 'آزمون'},
        'submitted_at': row.get('submitted_at'),
        'receipt_code': attempt_receipt_code(attempt_id),
    }
    answer_rows = _sx_attempt_rows(attempt_id, request.erd_profile_id)
    items = [
        {
            'index': index,
            # A recording / uploaded file alone is an answer too.
            'answered': bool(_sx_answer_value(item.get('answer'))) or bool(_sx_answer_files(item.get('answer_files'))),
            'marked': bool(item.get('marked')),
        }
        for index, item in enumerate(answer_rows, start=1)
    ]
    attempt_map = {
        'items': items,
        'answered_count': sum(1 for item in items if item['answered']),
        'marked_count': sum(1 for item in items if item['marked']),
    }
    return render(request, 'student/receipt.html', {'attempt': attempt, 'attempt_map': attempt_map})


def _sx_float(value, default=0):
    try:
        if value is None or value == '':
            return default
        return float(value)
    except (TypeError, ValueError):
        return default


def _sx_jalali(value):
    dt = _sx_dt(value)
    if not dt:
        return '-'
    dt = timezone.localtime(dt)  # the day in Tehran, not in UTC
    try:
        from .templatetags.core_extras import display_date_parts
        jy, jm, jd, _months = display_date_parts(dt.year, dt.month, dt.day)
        return f'{jy:04d}/{jm:02d}/{jd:02d}'
    except Exception:
        return dt.strftime('%Y/%m/%d')


def _to_jalali(value):
    from .templatetags.core_extras import to_jalali
    return to_jalali(value)


def _sx_percent(score, max_score):
    score = _sx_float(score)
    max_score = _sx_float(max_score)
    if max_score <= 0:
        return 0
    return max(0, min(100, round(score * 100 / max_score)))


RESULT_DISPLAY_MODES = {'after_publish': 'پس از انتشار نتایج', 'immediate': 'بلافاصله', 'manual': 'دستی'}
RESULT_RELEASE_COLUMNS = (
    'score_display_mode', 'correct_answer_display_mode', 'explanation_display_mode',
    'show_results_immediately', 'results_published_at',
    'exam_mode',  # practice exams release everything at once (see _exam_result_visibility)
    'total_score', 'passing_percent',  # the wizard's «مجموع نمرات کل آزمون» / «نمره قبولی (حداقل درصد)»
    'grading_template', 'settings_enforced',  # «قالب نمره‌دهی»: «فقط نمره‌ی کل» hides the per-question report
)


def _exam_result_columns(alias='e') -> tuple:
    """(SELECT list, GROUP BY suffix) for the exam's result-release columns; a missing column reads as NULL."""
    present = [column for column in RESULT_RELEASE_COLUMNS if erd_has_column('exams', column)]
    select = ', '.join(f'{alias}.{column}' if column in present else f'NULL AS {column}' for column in RESULT_RELEASE_COLUMNS)
    return select, ''.join(f', {alias}.{column}' for column in present)


def _exam_result_visibility(exam) -> dict:
    """What students may see of a graded attempt, from the wizard's «نمایش نمره / پاسخ صحیح / توضیح پاسخ».

    «بلافاصله» shows it once the attempt is graded; «پس از انتشار نتایج» and «دستی» wait until the teacher or
    the academic manager publishes the results. Exams created where the wizard field is not offered (quick
    create, bulk import) have no score mode and keep their «نمایش فوری نتیجه» flag.

    A practice exam («آزمون آزمایشی») is for learning and never reaches the transcript, so its score, key and
    explanations are shown as soon as the attempt is graded, whatever the display modes say."""
    published = bool(exam.get('results_published_at'))
    score_mode = exam.get('score_display_mode') or ('immediate' if exam.get('show_results_immediately') else 'after_publish')
    # «آزمون تمرینی» (training) is a self-check run through the normal exam pages: like a practice exam, the student
    # sees the score, key and explanations as soon as the attempt is graded.
    if exam.get('exam_mode') in (PRACTICE_EXAM_MODE, TRAINING_EXAM_MODE):
        score_mode = 'immediate'
        exam = {**exam, 'correct_answer_display_mode': 'immediate', 'explanation_display_mode': 'immediate'}

    def shown(mode):
        return published or mode == 'immediate'

    def detail_shown(mode):  # «پاسخ صحیح» / «توضیح پاسخ»: 'manual' is «نمایش داده نشود», even after publishing
        return mode != 'manual' and shown(mode)

    score = shown(score_mode)
    return {
        'published': published,
        'published_at': _sx_dt(exam.get('results_published_at')),
        'score_mode': score_mode,
        'score_mode_label': RESULT_DISPLAY_MODES.get(score_mode, RESULT_DISPLAY_MODES['after_publish']),
        'score': score,
        'correct_answers': score and detail_shown(exam.get('correct_answer_display_mode') or 'after_publish'),
        'explanations': score and detail_shown(exam.get('explanation_display_mode') or 'after_publish'),
        'per_question': not (exam.get('settings_enforced') and exam.get('grading_template') == 'total_score'),
    }


def _notify_published_result(attempt) -> None:
    create_notification(
        attempt['student_id'], 'نتیجه آزمون منتشر شد', f"نتیجه آزمون «{attempt['title']}» منتشر شد.",
        link=reverse('core:student_result_detail', args=[attempt['id']]), notification_type='exam_results',
    )


def _set_exam_results_published(request, exam_id, publish: bool) -> int:
    """Publish or withdraw an exam's results; on publishing, notify each student whose attempt is graded.

    Returns how many students were notified. Students graded later are notified when grading finishes.
    request is None when the release is automatic (exam_schedule.release_due_results)."""
    with transaction.atomic():
        erd_execute('UPDATE exams SET results_published_at = %s WHERE id = %s', [timezone.now() if publish else None, exam_id])
        graded = erd_rows(
            """
            SELECT ea.id, ea.student_id, e.title
            FROM exam_attempts ea JOIN exams e ON e.id = ea.exam_id
            WHERE ea.exam_id = %s AND ea.submitted_at IS NOT NULL AND COALESCE(ea.is_graded, false) = true
            """,
            [exam_id],
        ) if publish else []
        for attempt in graded:
            _notify_published_result(attempt)
    log_activity(
        request.user if request else None, 'exam_results_published' if publish else 'exam_results_withdrawn',
        ('نتایج آزمون منتشر شد.' if publish else 'انتشار نتایج آزمون لغو شد.') + ('' if request else ' (خودکار)'),
        request, {'exam_id': str(exam_id)},
    )
    return len(graded)


def _notify_if_result_released(attempt_id) -> None:
    """After manual grading finishes an attempt, tell the student when the exam's results are already visible."""
    select, _ = _exam_result_columns()
    attempt = erd_row(
        f"""
        SELECT ea.id, ea.student_id, ea.is_graded, e.title, {select}
        FROM exam_attempts ea JOIN exams e ON e.id = ea.exam_id
        WHERE ea.id = %s
        """,
        [attempt_id],
    )
    if attempt and attempt.get('is_graded') and _exam_result_visibility(attempt)['score']:
        _notify_published_result(attempt)


def _sx_result_status(row):
    is_graded = bool(row.get('is_graded')) and row.get('score') is not None
    if not is_graded:
        return 'در انتظار اعلام نتیجه', 'orange', True
    percent = row.get('percent', 0)
    if row.get('passing_percent') is not None:  # set by the wizard's «نمره قبولی (حداقل درصد)»
        return ('قبول', 'green', False) if percent >= _sx_float(row.get('passing_percent'), 60) else ('مردود', 'red', False)
    passing_score = _sx_float(row.get('passing_score'), 60)
    if passing_score <= 20:
        passing_percent = _sx_percent(passing_score, row.get('max_score') or 20)
    else:
        passing_percent = passing_score
    if percent >= passing_percent:
        return 'قبول', 'green', False
    return 'مردود', 'red', False


def _sx_result_rows(student_id, practice=None):
    """The student's submitted attempts; practice=False keeps course exams only, True practice exams only."""
    mode_filter = '' if practice is None else f"AND {_sx_exam_mode_sql()} {'=' if practice else '<>'} '{PRACTICE_EXAM_MODE}'"
    answer_present_expr = (
        "aa.answer IS NOT NULL AND aa.answer != ''"
        if connection.vendor == 'sqlite'
        else "aa.answer IS NOT NULL AND aa.answer::text NOT IN ('null', '\"\"')"
    )
    correct_answer_expr = "aa.is_correct = 1" if connection.vendor == 'sqlite' else "aa.is_correct IS TRUE"
    wrong_answer_expr = "aa.is_correct = 0" if connection.vendor == 'sqlite' else "aa.is_correct IS FALSE"
    release_select, release_group = _exam_result_columns()
    rows = erd_rows(
        f"""
        SELECT ea.id AS pk, ea.id, ea.exam_id, ea.student_id, ea.started_at, ea.submitted_at,
               ea.score, ea.max_score, ea.is_graded, ea.status,
               e.title, e.start_at, e.duration_minutes, COALESCE(e.passing_score, 60) AS passing_score,
               COALESCE(c.title, 'درس') AS course_title, {release_select},
               COUNT(DISTINCT eq.question_id) AS question_count,
               SUM(CASE WHEN {answer_present_expr} THEN 1 ELSE 0 END) AS answered_count,
               SUM(CASE WHEN {correct_answer_expr} THEN 1 ELSE 0 END) AS correct_count,
               SUM(CASE WHEN {wrong_answer_expr} AND {answer_present_expr} THEN 1 ELSE 0 END) AS wrong_count
        FROM exam_attempts ea
        JOIN exams e ON e.id = ea.exam_id
        LEFT JOIN courses c ON c.id = e.course_id
        LEFT JOIN exam_questions eq ON eq.exam_id = e.id
        LEFT JOIN attempt_answers aa ON aa.attempt_id = ea.id AND aa.question_id = eq.question_id
        WHERE ea.student_id = %s AND ea.submitted_at IS NOT NULL {mode_filter}
        GROUP BY ea.id, ea.exam_id, ea.student_id, ea.started_at, ea.submitted_at, ea.score, ea.max_score,
                 ea.is_graded, ea.status, e.title, e.start_at, e.duration_minutes, e.passing_score, c.title{release_group}
        ORDER BY ea.submitted_at DESC NULLS LAST, ea.started_at DESC NULLS LAST
        """,
        [student_id],
    )
    normalized = []
    for row in rows:
        question_count = _em_int(row.get('question_count'), 0)
        max_score = row.get('max_score')
        percent = _sx_percent(row.get('score'), max_score) if row.get('score') is not None and max_score else 0
        row['percent'] = percent
        label, tone, pending = _sx_result_status(row)
        visibility = _exam_result_visibility(row)
        awaiting_publication = not pending and not visibility['score']
        if awaiting_publication:
            label, tone, pending = 'در انتظار انتشار نتیجه', 'orange', True
        correct = _em_int(row.get('correct_count'), 0)
        wrong = _em_int(row.get('wrong_count'), 0)
        answered = _em_int(row.get('answered_count'), correct + wrong)
        if pending:  # nothing of the score may reach the page before it is graded and released
            percent, correct, wrong = 0, 0, 0
        normalized.append({
            'pk': row['pk'],
            'id': row['id'],
            'exam_id': row['exam_id'],
            'title': row.get('title') or 'آزمون',
            'course_title': row.get('course_title') or 'درس',
            'submitted_at': row.get('submitted_at'),
            'exam_date': _sx_jalali(row.get('start_at') or row.get('submitted_at')),
            'duration_minutes': _em_int(row.get('duration_minutes'), 90),
            'score': None if pending else row.get('score'),
            'max_score': max_score,
            'percent': percent,
            # The score on the exam's «مجموع نمرات کل آزمون» (out of 20 when the exam sets none).
            'scale': f'{_exam_score_scale(row):g}',
            'scaled_score': None if pending or not max_score else round(float(row.get('score') or 0) * _exam_score_scale(row) / float(max_score), 2),
            'status_label': label,
            'status_tone': tone,
            'is_pending': pending,
            'awaiting_publication': awaiting_publication,
            'visibility': visibility,
            'question_count': question_count,
            'answered_count': answered,
            'correct_count': correct,
            'wrong_count': wrong,
            'unanswered_count': max(question_count - answered, 0),
            'short_title': (row.get('title') or 'آزمون')[:18],
            'started_at': row.get('started_at'),
            'is_practice': row.get('exam_mode') == PRACTICE_EXAM_MODE,
        })
    return normalized


RESULT_OPTION_LETTERS = ['الف', 'ب', 'ج', 'د', 'هـ', 'و', 'ز', 'ح']
RESULT_CHOICE_KINDS = {'single', 'multi', 'true_false'}


def _sx_result_values(value):
    """A stored answer or key as a list of non-empty strings."""
    parsed = _sx_json(value, value)
    if isinstance(parsed, dict):
        parsed = parsed.get('value')
    values = parsed if isinstance(parsed, list) else [parsed]
    return [str(item).strip() for item in values if item is not None and str(item).strip()]


def _sx_result_answer_text(kind, values, row):
    """The student's answer in words for the non-choice question types."""
    if kind == 'ordering':
        items = sorted((item for item in (_sx_json(row.get('ordering_items'), []) or []) if isinstance(item, dict)),
                       key=lambda item: item.get('order', 0))
        texts = [str(item.get('text') or '') for item in items]
        steps = [part.strip() for part in (values[0] if values else '').split(',') if part.strip()]
        return ' ← '.join(texts[int(step) - 1] if step.isdigit() and 0 < int(step) <= len(texts) else step for step in steps)
    if kind == 'matching':
        pairs = [pair for pair in (_sx_json(row.get('matching_pairs'), []) or []) if isinstance(pair, dict)]
        shown = []
        for part in (values[0] if values else '').split(','):
            left, _, right = part.partition(':')
            left, right = left.strip(), right.strip()
            if left.isdigit() and right.isdigit() and 0 < int(left) <= len(pairs) and 0 < int(right) <= len(pairs):
                shown.append(f"{pairs[int(left) - 1].get('left', '')}: {pairs[int(right) - 1].get('right', '')}")
        return '، '.join(shown)
    if kind == 'hotspot':
        clicks = question_kinds.hotspot_clicks(values)
        return f'{len(clicks)} نقطه روی تصویر' if clicks else ''
    return ' | '.join(values)


def _sx_result_hotspot(row, answers):
    """Report-card view of a hotspot answer: the image, the student's clicks and (unless «فقط برای مدرس») the regions."""
    image = _sx_question_media(row.get('question_media')).get('image')
    if not image:
        return None
    settings_data = _sx_json(row.get('scoring_settings'), {}) or {}
    hotspot = settings_data.get('hotspot') or {} if isinstance(settings_data, dict) else {}
    clicks = question_kinds.hotspot_clicks(answers, hotspot.get('max_clicks') or 1)
    shapes = []
    if not hotspot.get('teacher_only', True):
        for region in _sx_json(row.get('accepted_answers'), []) or []:
            if not isinstance(region, dict):
                continue
            coords = region.get('coords') or []
            try:
                if region.get('shape') == 'rect':
                    (x1, y1), (x2, y2) = coords[0], coords[1]
                    shapes.append({'shape': 'rect', 'x': f'{x1:.2f}', 'y': f'{y1:.2f}', 'w': f'{x2 - x1:.2f}', 'h': f'{y2 - y1:.2f}', 'name': region.get('name', '')})
                elif region.get('shape') == 'circle':
                    (cx, cy), (rx, ry) = coords[0], coords[1]
                    shapes.append({'shape': 'circle', 'cx': f'{cx:.2f}', 'cy': f'{cy:.2f}', 'rx': f'{rx:.2f}', 'ry': f'{ry:.2f}', 'name': region.get('name', '')})
                elif region.get('shape') == 'polygon':
                    shapes.append({'shape': 'polygon', 'points': ' '.join(f'{x:.2f},{y:.2f}' for x, y in coords), 'name': region.get('name', '')})
            except (TypeError, ValueError, IndexError):
                continue
    return {
        'image': image,
        'image_alt': _sx_question_media(row.get('question_media')).get('image_alt', ''),
        'clicks': [{'left': f'{x:.2f}', 'top': f'{y:.2f}'} for x, y in clicks],
        'regions': shapes,
    }


def _sx_result_question_rows(attempt_id, student_id):
    """The attempt's questions as graded, from stored data only.

    tone: good = full points, partial = some points, bad = answered without points, empty = not answered."""
    optional = ', '.join(
        f'q.{column}' if erd_has_column('questions', column) else f'NULL AS {column}'
        for column in ('ordering_items', 'matching_pairs', 'subject', 'feedback', 'question_media', 'accepted_answers', 'scoring_settings')
    )
    files = 'aa.answer_files' if erd_has_column('attempt_answers', 'answer_files') else 'NULL AS answer_files'
    rows = erd_rows(
        f"""
        SELECT q.id AS question_id, q.text, COALESCE(q.type, 'single') AS type, q.options, q.correct_answer,
               COALESCE(q.explanation, '') AS explanation, {optional},
               COALESCE(eq.points, q.default_points, 0) AS max_points,
               aa.answer, aa.is_correct, aa.points_awarded, aa.grader_feedback, {files}
        FROM exam_attempts ea
        JOIN exam_questions eq ON eq.exam_id = ea.exam_id
        JOIN questions q ON q.id = eq.question_id
        LEFT JOIN attempt_answers aa ON aa.attempt_id = ea.id AND aa.question_id = q.id
        WHERE ea.id = %s AND ea.student_id = %s
        ORDER BY eq.order_index NULLS LAST, q.id
        """,
        [attempt_id, student_id],
    )
    items = []
    for index, row in enumerate(rows, start=1):
        kind = row.get('type') or 'single'
        answers = _sx_result_values(row.get('answer'))
        answered = bool(answers or _sx_answer_files(row.get('answer_files')))
        options = []
        if kind in RESULT_CHOICE_KINDS:
            key = set(_sx_result_values(row.get('correct_answer')))
            options = [
                {**option, 'letter': RESULT_OPTION_LETTERS[number] if number < len(RESULT_OPTION_LETTERS) else str(number + 1),
                 'chosen': option['value'] in answers, 'correct': option['value'] in key}
                for number, option in enumerate(_sx_question_options(row.get('options'), kind))
            ]
        points, max_points = _sx_float(row.get('points_awarded'), 0), _sx_float(row.get('max_points'), 0)
        notes = _sx_json(row.get('feedback'), {}) or {}  # the question builder's «توضیح بازخورد» is notes['text']
        notes = notes if isinstance(notes, dict) else {}
        if not answered:
            tone = 'empty'
        elif row.get('is_correct') in (True, 1, '1', 'true', 't') or (max_points and points >= max_points):
            tone = 'good'
        elif points > 0:
            tone = 'partial'
        else:
            tone = 'bad'
        items.append({
            'index': index,
            'question_id': row.get('question_id'),
            'text': str(row.get('text') or '').strip(),
            'type': kind,
            'type_label': _sx_type_label(kind),
            'options': options,
            'answer_text': '' if options else _sx_result_answer_text(kind, answers, row),
            'points': points,
            'max_points': max_points,
            'tone': tone,
            # The builder saves its «بازخورد کلی» in feedback.text; older questions have an explanation column.
            'explanation': str(row.get('explanation') or '').strip() or str(notes.get('text') or '').strip(),
            'feedback': str(row.get('grader_feedback') or '').strip(),
            'subject': str(row.get('subject') or '').strip(),
            'builder_note': str(notes.get('text') or '').strip(),
            'resource': question_resource(notes),
            'hotspot': _sx_result_hotspot(row, answers) if kind == 'hotspot' else None,
            # Recorded / uploaded answer files (audio, video, image, document), playable on the report card.
            'files': [{**item, 'url': reverse('core:attempt_answer_file', args=[attempt_id, item['id']])}
                      for item in _sx_answer_files(row.get('answer_files'))],
        })
    return items


@erd_role_required('student')
def student_result_detail(request, attempt_id):
    result = next((item for item in _sx_result_rows(request.erd_profile_id) if str(item['id']) == str(attempt_id)), None)
    if result:
        result['receipt_code'] = attempt_receipt_code(attempt_id)
    if not result:
        raise Http404('نتیجه آزمون پیدا نشد.')
    if result['is_practice']:
        from . import student_practice as practice

        if result['is_pending']:  # a manually graded question is still waiting for the teacher
            return redirect('core:student_attempt_receipt', attempt_id=attempt_id)
        return render(request, 'student/practice_result.html', {
            'student': _sx_student_context(request),
            'practice_nav': True,
            'result': result,
            **practice.result_context(result, attempt_id, request.erd_profile_id),
        })
    if result['is_pending']:
        return render(request, 'student/result_detail.html', {
            'student': _sx_student_context(request),
            'result': result,
            'is_pending': True,
        })
    question_items = _sx_result_question_rows(attempt_id, request.erd_profile_id)
    tones = [item['tone'] for item in question_items]
    summary = {
        'total': len(question_items),
        'correct': tones.count('good'),
        'partial': tones.count('partial'),
        'wrong': tones.count('bad'),
        'unanswered': tones.count('empty'),
    }
    try:
        current_index = int(request.GET.get('q') or 1)
    except ValueError:
        current_index = 1
    current_index = min(max(current_index, 1), len(question_items) or 1)
    current_question = question_items[current_index - 1] if question_items else None
    rank, rank_total = _sx_result_rank(result['exam_id'], result['score'])
    return render(request, 'student/result_detail.html', {
        'student': _sx_student_context(request),
        'result': result,
        'is_pending': False,
        'question_items': question_items,
        'current_question': current_question,
        'summary': summary,
        'rank': rank,
        'rank_total': rank_total,
        'topics': _sx_result_topics(attempt_id),
        'show_correct': result['visibility']['correct_answers'],
        'show_explanation': result['visibility']['explanations'],
    })


def _sx_result_rank(exam_id, score):
    """(rank, participants) among students with a graded attempt on the exam, by each student's best score.

    Students with the same score share a rank. (None, 0) while this attempt has no score."""
    if score is None:
        return None, 0
    row = erd_row(
        """
        SELECT COUNT(*) AS total, SUM(CASE WHEN best > %s THEN 1 ELSE 0 END) AS ahead
        FROM (
            SELECT student_id, MAX(score) AS best
            FROM exam_attempts
            WHERE exam_id = %s AND COALESCE(is_graded, false) = true AND score IS NOT NULL
            GROUP BY student_id
        ) graded
        """,
        [score, exam_id],
    ) or {}
    total = _em_int(row.get('total'), 0)
    return (_em_int(row.get('ahead'), 0) + 1, total) if total else (None, 0)


def _sx_result_topics(attempt_id):
    """Score percentage per question subject («مبحث») of one attempt, most questions first."""
    rows = erd_rows(
        """
        SELECT TRIM(q.subject) AS subject, COUNT(*) AS question_count,
               SUM(COALESCE(eq.points, 0)) AS max_points, SUM(COALESCE(aa.points_awarded, 0)) AS awarded
        FROM exam_attempts ea
        JOIN exam_questions eq ON eq.exam_id = ea.exam_id
        JOIN questions q ON q.id = eq.question_id
        LEFT JOIN attempt_answers aa ON aa.attempt_id = ea.id AND aa.question_id = q.id
        WHERE ea.id = %s AND COALESCE(TRIM(q.subject), '') != ''
        GROUP BY TRIM(q.subject)
        ORDER BY COUNT(*) DESC, TRIM(q.subject)
        """,
        [attempt_id],
    )
    return [
        {
            'title': row['subject'],
            'percent': round(min(max(_sx_float(row['awarded'], 0) / _sx_float(row['max_points'], 0) * 100, 0), 100)),
        }
        for row in rows if _sx_float(row['max_points'], 0) > 0
    ]



@login_required
def profile_view(request):
    page_context = erd_profile_page_context(request.user)
    if not page_context:
        messages.error(request, 'پروفایل کاربری شما در سامانه پیدا نشد.')
        return redirect('core:dashboard')
    # «پروفایل من» (the name in the panel chrome): each role's own, working account page.
    role = erd_primary_role(request.user)
    section = request.GET.get('section')
    if role == 'student':
        old_sections = {'security': 'security', 'announcements': 'workspace'}
        return redirect(f'{reverse("core:student_settings")}?tab={old_sections.get(section, "personal")}')
    if role == 'teacher':
        return redirect(f'{reverse("core:teacher_settings")}?tab={"security" if section in ("security", "sessions") else "personal"}')
    return _legacy_profile_view(request)


# --- Passwords: a super admin sets another account's password; forced change after a temporary one ---------------
# Passwords are stored only as Django hashes, so nobody can see one. A super admin can give an account a new password
# (generated and shown once, or typed) after confirming their own password; super admin accounts are excluded (each
# changes their own from «پروفایل من»). Every session of that account is ended, and by default its owner must pick a
# new password at the next sign-in (profiles.password_change_required, PasswordChangeRequiredMiddleware).

ADMIN_PASSWORD_KINDS = {
    # URL kind → (role the account must have, its edit page)
    'teacher': ('teacher', 'core:super_admin_teacher_profile_edit'),
    'student': ('student', 'core:super_admin_student_profile_edit'),
    'manager': ('academic_manager', 'core:super_admin_manager_profile_edit'),
}
PASSWORD_REVEAL_SESSION_KEY = 'admin_password_reveal'


def _admin_password_target(kind, user_id):
    """(profile row, roles) of the account a super admin may set a password for, or Http404."""
    if kind not in ADMIN_PASSWORD_KINDS:
        raise Http404('نوع حساب نامعتبر است.')
    profile = erd_row(
        'SELECT id, username, full_name, status, password_changed_at, password_change_required FROM profiles WHERE id = %s',
        [user_id],
    )
    roles = erd_roles_for_profile(profile['id']) if profile else []
    if not profile or ADMIN_PASSWORD_KINDS[kind][0] not in roles:
        raise Http404('حساب پیدا نشد.')
    return profile, roles


def admin_password_card_context(request, kind, user_id) -> dict:
    """Context of the «رمز عبور» card on a user's edit page; pops the one-time display of a generated password."""
    try:
        profile, roles = _admin_password_target(kind, user_id)
    except Http404:
        return {'missing': True}  # e.g. a manager page opened for an account without that role: no card
    reveal = None
    pending = request.session.get(PASSWORD_REVEAL_SESSION_KEY)
    if pending and pending.get('profile_id') == str(profile['id']):
        reveal = request.session.pop(PASSWORD_REVEAL_SESSION_KEY).get('password')
    return {
        'action_url': reverse('core:super_admin_set_user_password', args=[kind, user_id]),
        'changed_at': erd_datetime(profile.get('password_changed_at')),
        'change_required': bool(profile.get('password_change_required')),
        'username': profile.get('username') or '',
        'is_admin': 'admin' in roles,
        'reveal': reveal,
    }


@super_admin_required
def super_admin_set_user_password(request, kind, user_id):
    profile, roles = _admin_password_target(kind, user_id)
    edit_url = f'{reverse(ADMIN_PASSWORD_KINDS[kind][1], args=[user_id])}#account-password'
    if request.method != 'POST':
        return redirect(edit_url)
    username = (profile.get('username') or '').strip()
    mode = 'manual' if request.POST.get('password_mode') == 'manual' else 'generate'
    change_required = request.POST.get('change_required') == '1'
    errors = []
    if 'admin' in roles:
        errors.append('رمز حساب مدیر کل را فقط خود او از «پروفایل من» تغییر می‌دهد.')
    elif not username:
        errors.append('این حساب نام کاربری ندارد؛ ابتدا نام کاربری را ثبت کنید.')
    elif username == request.user.username:
        errors.append('رمز حساب خودتان را از «پروفایل من» تغییر دهید.')
    elif not request.user.check_password(request.POST.get('admin_password') or ''):
        errors.append('رمز عبور فعلی شما نادرست است.')
        log_activity(
            request.user, 'password_reset_failed',
            f'رمز نادرست هنگام تعیین رمز برای {profile.get("full_name") or username}', request,
            {'profile_id': str(profile['id'])},
        )
    target = None
    new_password = ''
    if not errors:
        target = User.objects.filter(username=username).first() or User(username=username, is_active=(profile.get('status') == 'active'))
        if mode == 'manual':
            new_password = request.POST.get('new_password1') or ''
            if not new_password:
                errors.append('رمز عبور جدید را وارد کنید.')
            elif new_password != (request.POST.get('new_password2') or ''):
                errors.append('تکرار رمز عبور جدید با خود آن یکسان نیست.')
            else:
                try:
                    validate_password(new_password, user=target)
                except ValidationError as exc:
                    errors.extend(exc.messages)
        else:
            new_password = account_security.generate_temporary_password()
    if errors:
        for error in errors:
            messages.error(request, error)
        return redirect(edit_url)

    with transaction.atomic():
        target.set_password(new_password)
        target.save()
        account_security.mark_password_set(target, change_required=change_required)
    account_security.end_all_sessions(target)
    log_activity(
        request.user, 'password_reset_by_admin',
        f'تعیین رمز عبور جدید برای {profile.get("full_name") or username}', request,
        {'profile_id': str(profile['id']), 'mode': mode, 'change_required': change_required},
    )
    if mode == 'generate':
        request.session[PASSWORD_REVEAL_SESSION_KEY] = {'profile_id': str(profile['id']), 'password': new_password}
    messages.success(request, 'رمز عبور جدید ثبت شد و همه‌ی نشست‌های باز این کاربر بسته شد.')
    return redirect(edit_url)


@login_required
def password_change_required_view(request):
    """The only page an account with a temporary password can open until its owner chooses a new password."""
    profile = erd_profile_for_user(request.user)
    next_url = request.POST.get('next') or request.GET.get('next') or ''
    if not url_has_allowed_host_and_scheme(next_url, allowed_hosts={request.get_host()}, require_https=request.is_secure()):
        next_url = ''
    if not (profile and profile.get('password_change_required')):
        return redirect(next_url or 'core:dashboard')
    form = SetPasswordForm(request.user, request.POST or None)
    if request.method == 'POST' and form.is_valid():
        if request.user.check_password(form.cleaned_data['new_password1']):
            form.add_error('new_password1', 'رمز جدید باید با رمز موقت فرق داشته باشد.')
        else:
            form.save()
            update_session_auth_hash(request, form.user)
            account_security.mark_password_set(form.user)
            account_security.end_other_sessions(form.user, request.session.session_key)
            log_activity(request.user, 'password_changed', 'تعیین رمز عبور جدید به‌جای رمز موقت', request)
            messages.success(request, 'رمز عبور جدید شما ثبت شد.')
            return redirect(next_url or 'core:dashboard')
    return render(request, 'account/password_change_required.html', {
        'form': form,
        'errors': [error for errors in form.errors.values() for error in errors] if form.is_bound else [],
        'next': next_url,
        'display_name': profile.get('full_name') or request.user.username,
    })


